:root {
  --ink: #05070a;
  --ink-soft: #0a0d12;
  --bone: #e7ddc8;
  --bone-dim: #9c9587;
  --gold: #d8ad63;
  --gold-bright: #f6d28b;
  --ember: #e76d36;
  --blood: #a52e2b;
  --soul: #82e6ff;
  --soul-deep: #2e8fc1;
  --panel: rgba(8, 10, 14, 0.84);
  --serif: "Cinzel", "Palatino Linotype", "Book Antiqua", Palatino, serif;
  --body: "EB Garamond", Garamond, Georgia, serif;
}

* {
  box-sizing: border-box;
}

html,
body {
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: var(--ink);
}

body {
  font-family: var(--body);
  color: var(--bone);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overscroll-behavior: none;
  user-select: none;
  -webkit-user-select: none;
}

button {
  font: inherit;
  color: inherit;
  border: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

button:focus-visible {
  outline: 1px solid var(--gold-bright);
  outline-offset: 5px;
}

#game {
  position: fixed;
  inset: 0;
  isolation: isolate;
  background:
    radial-gradient(circle at 50% 40%, #0b1117 0%, #05070a 60%, #020304 100%);
  overflow: hidden;
}

#gameCanvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
}

.grain {
  position: absolute;
  inset: -50%;
  z-index: 3;
  pointer-events: none;
  opacity: 0.055;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 240 240' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.82' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.75'/%3E%3C/svg%3E");
  background-size: 240px 240px;
  mix-blend-mode: soft-light;
  animation: grain-shift 0.7s steps(2) infinite;
}

@keyframes grain-shift {
  0% { transform: translate3d(0, 0, 0); }
  25% { transform: translate3d(-3%, 2%, 0); }
  50% { transform: translate3d(2%, -1%, 0); }
  75% { transform: translate3d(-1%, -3%, 0); }
  100% { transform: translate3d(3%, 1%, 0); }
}

.vignette {
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  background:
    radial-gradient(ellipse at 50% 48%, transparent 35%, rgba(0, 0, 0, 0.34) 72%, rgba(0, 0, 0, 0.78) 100%),
    linear-gradient(180deg, rgba(0, 0, 0, 0.44) 0%, transparent 16%, transparent 78%, rgba(0, 0, 0, 0.6) 100%);
}

/* ------- HUD ------- */

.hud {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  z-index: 10;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding:
    max(20px, env(safe-area-inset-top))
    max(26px, calc(env(safe-area-inset-right) + 20px))
    0
    max(26px, calc(env(safe-area-inset-left) + 20px));
  opacity: 0;
  transform: translateY(-8px);
  transition: opacity 0.45s ease, transform 0.45s ease;
  pointer-events: none;
  background: linear-gradient(180deg, rgba(2, 4, 7, 0.7) 0%, transparent 100%);
  padding-bottom: 36px;
}

body[data-state="playing"] .hud,
body[data-state="boss"] .hud,
body[data-state="bossDefeat"] .hud,
body[data-state="dying"] .hud {
  opacity: 1;
  transform: translateY(0);
}

.hud-left {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.flasks {
  display: flex;
  gap: 5px;
  filter: drop-shadow(0 2px 5px rgba(0, 0, 0, 0.8));
}

.flask {
  display: block;
  width: 25px;
  height: 31px;
  color: #292b2e;
  opacity: 0.7;
  transform-origin: 50% 90%;
  transition: color 0.35s ease, opacity 0.35s ease, transform 0.35s ease, filter 0.35s ease;
}

.flask svg {
  display: block;
  width: 100%;
  height: 100%;
}

.flask.is-full {
  color: #c9974f;
  opacity: 1;
  filter: drop-shadow(0 0 7px rgba(240, 141, 58, 0.38));
}

.flask.just-filled {
  animation: flask-fill 0.75s ease both;
}

.flask.just-lost {
  animation: flask-lost 0.5s ease both;
}

@keyframes flask-fill {
  0% { transform: scale(0.65); filter: brightness(3) drop-shadow(0 0 20px #ffb552); }
  60% { transform: scale(1.22); }
  100% { transform: scale(1); }
}

@keyframes flask-lost {
  0% { transform: scale(1.25) rotate(-6deg); filter: brightness(2); }
  100% { transform: scale(1) rotate(0); }
}

.run-stats {
  display: flex;
  align-items: center;
  gap: 9px;
  font-family: var(--serif);
  font-size: 12px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(227, 218, 198, 0.7);
  text-shadow: 0 2px 8px #000;
}

.run-stats b {
  color: var(--bone);
  font-weight: 600;
}

.soul-readout {
  display: flex;
  align-items: center;
  gap: 7px;
}

.soul-gem {
  width: 10px;
  height: 10px;
  display: inline-block;
  background: var(--soul);
  transform: rotate(45deg);
  box-shadow: 0 0 8px rgba(130, 230, 255, 0.9), 0 0 20px rgba(74, 179, 225, 0.45);
  border: 1px solid rgba(230, 254, 255, 0.8);
}

.stat-divider {
  opacity: 0.38;
}

.hud-right {
  display: flex;
  align-items: center;
  gap: 9px;
  pointer-events: auto;
}

.icon-btn {
  width: 38px;
  height: 38px;
  padding: 8px;
  display: grid;
  place-items: center;
  color: rgba(224, 214, 195, 0.67);
  border: 1px solid rgba(204, 181, 142, 0.18);
  background: rgba(4, 6, 9, 0.48);
  backdrop-filter: blur(4px);
  transition: border-color 0.2s ease, color 0.2s ease, background 0.2s ease;
}

.icon-btn:hover {
  color: var(--gold-bright);
  border-color: rgba(232, 193, 124, 0.55);
  background: rgba(15, 16, 20, 0.8);
}

.icon-btn svg {
  width: 100%;
  height: 100%;
}

.icon-muted {
  display: none;
}

body.is-muted .icon-sound {
  display: none;
}

body.is-muted .icon-muted {
  display: block;
}

/* ------- Boss UI ------- */

.boss-hud {
  position: absolute;
  z-index: 11;
  top: max(76px, calc(env(safe-area-inset-top) + 68px));
  left: 50%;
  width: min(620px, 60vw);
  transform: translate(-50%, -15px);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.7s ease, transform 0.7s ease;
  filter: drop-shadow(0 6px 20px rgba(0, 0, 0, 0.8));
}

.boss-hud.is-active {
  opacity: 1;
  transform: translate(-50%, 0);
}

.boss-heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 8px;
  padding: 0 3px;
}

.boss-kicker {
  font-family: var(--serif);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.36em;
  color: rgba(194, 159, 105, 0.8);
  text-transform: uppercase;
  white-space: nowrap;
}

.boss-heading h2 {
  margin: 0;
  font-family: var(--serif);
  font-size: clamp(13px, 1.3vw, 17px);
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: #eadcc2;
  text-align: right;
  text-shadow: 0 2px 10px #000;
}

.boss-track {
  position: relative;
  height: 9px;
  padding: 2px;
  background: rgba(2, 3, 5, 0.78);
  border: 1px solid rgba(188, 153, 100, 0.38);
  box-shadow: inset 0 0 6px rgba(0, 0, 0, 0.9);
}

.boss-track-inner {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: rgba(66, 20, 19, 0.42);
}

.boss-fill {
  width: 100%;
  height: 100%;
  background:
    linear-gradient(180deg, rgba(255, 221, 163, 0.22), transparent 52%),
    linear-gradient(90deg, #8f2826 0%, #c64334 48%, #eb7c45 100%);
  box-shadow: 0 0 10px rgba(220, 78, 52, 0.55);
  transition: width 0.18s ease-out;
}

.boss-track::before,
.boss-track::after {
  content: "";
  position: absolute;
  top: 50%;
  width: 10px;
  height: 10px;
  border: 1px solid rgba(200, 164, 106, 0.58);
  background: #080a0e;
  transform: translateY(-50%) rotate(45deg);
}

.boss-track::before { left: -7px; }
.boss-track::after { right: -7px; }

.boss-ember {
  position: absolute;
  top: 50%;
  left: 100%;
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: #ffdba1;
  box-shadow: 0 0 7px 2px rgba(255, 118, 53, 0.8);
  transform: translate(-2px, -50%);
  animation: ember-pulse 1.3s ease-in-out infinite;
}

@keyframes ember-pulse {
  0%, 100% { opacity: 0.5; }
  50% { opacity: 1; }
}

/* ------- Touch combat ------- */

.cast-btn {
  position: absolute;
  z-index: 12;
  right: max(26px, calc(env(safe-area-inset-right) + 22px));
  bottom: max(30px, calc(env(safe-area-inset-bottom) + 24px));
  width: 84px;
  height: 84px;
  display: grid;
  place-items: center;
  color: rgba(156, 225, 239, 0.9);
  border-radius: 50%;
  border: 1px solid rgba(118, 201, 221, 0.35);
  background:
    radial-gradient(circle, rgba(55, 137, 165, 0.18) 0%, rgba(5, 13, 18, 0.76) 62%, rgba(3, 7, 10, 0.86) 100%);
  box-shadow: 0 0 22px rgba(40, 120, 150, 0.12), inset 0 0 15px rgba(110, 220, 255, 0.08);
  opacity: 0;
  transform: scale(0.8);
  transition: opacity 0.35s ease, transform 0.35s ease, border-color 0.2s ease;
  pointer-events: none;
  touch-action: none;
}

.cast-btn svg {
  width: 46%;
  height: 46%;
  filter: drop-shadow(0 0 5px rgba(104, 222, 255, 0.55));
}

.cast-label {
  position: absolute;
  bottom: 10px;
  font-family: var(--serif);
  font-size: 8px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: rgba(157, 216, 230, 0.65);
}

.cast-ring {
  position: absolute;
  inset: 7px;
  border-radius: 50%;
  border: 1px dashed rgba(130, 220, 240, 0.22);
  animation: ring-turn 18s linear infinite;
}

@keyframes ring-turn {
  to { transform: rotate(360deg); }
}

.cast-btn.is-cooling {
  border-color: rgba(118, 201, 221, 0.14);
  opacity: 0.55;
}

body[data-state="playing"] .cast-btn,
body[data-state="boss"] .cast-btn {
  opacity: 0.9;
  transform: scale(1);
  pointer-events: auto;
}

body[data-state="playing"] .cast-btn:active,
body[data-state="boss"] .cast-btn:active {
  transform: scale(0.92);
  border-color: rgba(173, 240, 255, 0.8);
  background:
    radial-gradient(circle, rgba(101, 212, 245, 0.38) 0%, rgba(5, 13, 18, 0.78) 64%);
}

/* ------- Hint ------- */

.hint {
  position: absolute;
  z-index: 9;
  left: 50%;
  bottom: max(34px, calc(env(safe-area-inset-bottom) + 28px));
  transform: translate(-50%, 8px);
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 8px 18px;
  font-family: var(--serif);
  font-size: 10px;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: rgba(222, 212, 192, 0.52);
  background: rgba(5, 7, 10, 0.45);
  border-top: 1px solid rgba(210, 181, 133, 0.12);
  border-bottom: 1px solid rgba(210, 181, 133, 0.12);
  backdrop-filter: blur(3px);
  opacity: 0;
  transition: opacity 0.6s ease, transform 0.6s ease;
  pointer-events: none;
}

body[data-state="playing"] .hint {
  opacity: 1;
  transform: translate(-50%, 0);
}

body[data-state="playing"] .hint.is-hidden {
  opacity: 0;
}

.hint em {
  font-style: normal;
  color: rgba(238, 221, 193, 0.86);
}

.hint kbd {
  display: inline-block;
  min-width: 22px;
  margin-right: 4px;
  padding: 2px 5px;
  font-family: var(--serif);
  font-size: 8px;
  color: rgba(240, 222, 190, 0.8);
  border: 1px solid rgba(213, 188, 146, 0.25);
  background: rgba(16, 18, 22, 0.8);
}

.hint-sep {
  width: 1px;
  height: 15px;
  background: rgba(221, 196, 151, 0.18);
}

/* ------- Banner ------- */

.banner {
  position: absolute;
  z-index: 12;
  top: 24%;
  left: 50%;
  width: min(680px, 90vw);
  transform: translate(-50%, 12px);
  text-align: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.7s ease, transform 0.7s ease;
}

.banner.is-visible {
  opacity: 1;
  transform: translate(-50%, 0);
}

.banner::before,
.banner::after {
  content: "";
  display: block;
  height: 1px;
  margin: 0 auto 11px;
  background: linear-gradient(90deg, transparent, rgba(207, 171, 110, 0.58), transparent);
}

.banner::after {
  margin: 11px auto 0;
}

.banner span {
  font-family: var(--serif);
  font-size: 9px;
  letter-spacing: 0.44em;
  text-transform: uppercase;
  color: rgba(207, 170, 105, 0.8);
}

.banner h2 {
  margin: 9px 0 0;
  font-family: var(--serif);
  font-size: clamp(24px, 3.7vw, 46px);
  font-weight: 500;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: #efe1c9;
  text-shadow: 0 4px 24px #000, 0 0 32px rgba(212, 167, 98, 0.15);
}

.banner.is-gold h2 {
  color: var(--gold-bright);
  text-shadow: 0 4px 30px #000, 0 0 25px rgba(242, 185, 90, 0.35);
}

.banner.is-blood h2 {
  color: #dfb0a1;
}

/* ------- Screens and menus ------- */

.screen {
  position: absolute;
  inset: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity 0.55s ease, visibility 0.55s;
}

.screen.is-visible {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
}

.title-screen {
  align-items: center;
  justify-content: flex-start;
