}

.title-screen.is-visible .title-inner > :nth-child(1) { animation-delay: 0.08s; }
.title-screen.is-visible .title-inner > :nth-child(2) { animation-delay: 0.16s; }
.title-screen.is-visible .title-inner > :nth-child(3) { animation-delay: 0.26s; }
.title-screen.is-visible .title-inner > :nth-child(4) { animation-delay: 0.38s; }
.title-screen.is-visible .title-inner > :nth-child(5) { animation-delay: 0.5s; }
.title-screen.is-visible .title-inner > :nth-child(6) { animation-delay: 0.6s; }

@keyframes title-rise {
  from { opacity: 0; transform: translateY(18px); filter: blur(5px); }
  to { opacity: 1; transform: translateY(0); filter: blur(0); }
}

.title-inner {
  width: min(560px, 54vw);
