  font-weight: 800;
  font-style: normal;
  letter-spacing: -0.02em;
  background: linear-gradient(178deg, #fff3d8 0%, #e7bb72 38%, #b56c36 68%, #7d3d26 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  text-shadow: none;
}

.tagline {
  margin: 27px 0 0;
  font-size: clamp(19px, 1.75vw, 27px);
  line-height: 1.28;
  font-weight: 400;
  color: rgba(223, 213, 194, 0.69);
}

.tagline em {
  color: rgba(242, 226, 200, 0.9);
}

.ornate-btn {
  position: relative;
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-width: 210px;
  margin-top: 36px;
  padding: 15px 38px 13px;
  color: #20160c;
  background: linear-gradient(180deg, #f1d093 0%, #d7a85c 45%, #b47933 100%);
  border: 1px solid rgba(255, 238, 199, 0.58);
  outline: 1px solid rgba(214, 169, 99, 0.4);
  outline-offset: 4px;
  clip-path: polygon(12px 0, calc(100% - 12px) 0, 100% 12px, 100% calc(100% - 12px), calc(100% - 12px) 100%, 12px 100%, 0 calc(100% - 12px), 0 12px);
  box-shadow: 0 0 40px rgba(231, 169, 80, 0.18), inset 0 1px rgba(255, 255, 255, 0.35);
  transition: transform 0.2s ease, filter 0.2s ease, box-shadow 0.2s ease;
  overflow: hidden;
  isolation: isolate;
}

.ornate-btn::before,
.ornate-btn::after {
  content: "";
  position: absolute;
  top: 50%;
  width: 23px;
  height: 1px;
  background: rgba(52, 32, 11, 0.52);
}

.ornate-btn::before { left: 13px; }
.ornate-btn::after { right: 13px; }

.ornate-btn:hover {
  transform: translateY(-2px);
  filter: brightness(1.12);
  box-shadow: 0 0 50px rgba(251, 190, 96, 0.33), inset 0 1px rgba(255, 255, 255, 0.5);
}

.ornate-btn:active {
  transform: translateY(1px) scale(0.995);
  filter: brightness(0.97);
}

.btn-label {
  position: relative;
  z-index: 2;
  font-family: var(--serif);
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0.22em;
  text-transform: uppercase;
}

.btn-sub {
  position: relative;
  z-index: 2;
  margin-top: 2px;
  font-size: 10px;
  font-style: italic;
  letter-spacing: 0.09em;
  opacity: 0.65;
}

.btn-flare {
  position: absolute;
  top: -120%;
  left: -30%;
  width: 40%;
  height: 340%;
  background: linear-gradient(90deg, transparent, rgba(255, 250, 231, 0.65), transparent);
  transform: rotate(18deg);
  transition: left 0.65s ease;
  z-index: 1;
}

.ornate-btn:hover .btn-flare {
