}

.title-controls {
  display: flex;
  align-items: center;
  gap: 24px;
  margin-top: 30px;
  padding-top: 18px;
  border-top: 1px solid rgba(207, 178, 127, 0.14);
  font-family: var(--serif);
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(208, 199, 181, 0.47);
}

.title-controls span {
  display: flex;
  align-items: center;
  gap: 7px;
}

.title-controls kbd {
  display: inline-grid;
  place-items: center;
  min-width: 24px;
  height: 22px;
  padding: 0 5px;
  font-family: var(--serif);
  font-size: 8px;
  color: rgba(231, 219, 197, 0.77);
  border: 1px solid rgba(210, 182, 138, 0.25);
  background: rgba(14, 16, 20, 0.68);
}

.title-controls i {
  font-style: normal;
  color: rgba(222, 213, 196, 0.37);
}

.record {
  margin: 22px 0 0;
  font-family: var(--serif);
  font-size: 8px;
  letter-spacing: 0.29em;
  text-transform: uppercase;
  color: rgba(205, 176, 125, 0.52);
}

.record b {
  color: rgba(231, 198, 137, 0.82);
  font-weight: 600;
  letter-spacing: 0.13em;
}

.title-foot {
  position: absolute;
  left: max(8vw, 30px);
  bottom: max(22px, calc(env(safe-area-inset-bottom) + 16px));
  margin: 0;
  font-size: 12px;
  font-style: italic;
  letter-spacing: 0.03em;
  color: rgba(210, 200, 180, 0.3);
}

/* ------- Modal screens ------- */

.modal-screen {
  align-items: center;
  justify-content: center;
  padding: max(24px, env(safe-area-inset-top)) 20px max(24px, env(safe-area-inset-bottom));
  background:
    radial-gradient(ellipse at 50% 44%, rgba(17, 23, 28, 0.6) 0%, rgba(3, 4, 7, 0.91) 62%, rgba(2, 3, 5, 0.97) 100%);
  backdrop-filter: blur(5px);
}

.modal-screen.is-visible .modal {
  animation: modal-in 0.55s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

@keyframes modal-in {
  from { opacity: 0; transform: translateY(14px) scale(0.985); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

.modal {
  width: min(520px, 92vw);
  text-align: center;
}

.modal .eyebrow {
  justify-content: center;
}

.modal-title,
.victory-title,
.death-title {
  margin: 0;
  font-family: var(--serif);
  font-weight: 500;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  line-height: 1;
}

.modal-title {
  font-size: clamp(42px, 6vw, 68px);
  color: #e7ddc9;
}

.modal-copy {
  margin: 19px auto 0;
  max-width: 34ch;
  font-size: 18px;
  line-height: 1.4;
  font-style: italic;
  color: rgba(211, 201, 181, 0.56);
}

.text-btn {
  display: block;
  margin: 17px auto 0;
  padding: 7px 12px;
  font-family: var(--serif);
  font-size: 9px;
  letter-spacing: 0.25em;
  text-transform: uppercase;
  color: rgba(206, 193, 169, 0.38);
  transition: color 0.2s ease;
}

.text-btn:hover {
  color: rgba(238, 210, 161, 0.85);
}

.danger {
  color: rgba(203, 91, 80, 0.8) !important;
}

.death-title {
  font-size: clamp(58px, 9vw, 112px);
  color: #7d2626;
  letter-spacing: 0.04em;
  text-shadow: 0 0 50px rgba(154, 37, 34, 0.28), 0 6px 0 rgba(24, 4, 4, 0.35);
  animation: death-flicker 4s ease-in-out infinite;
}

@keyframes death-flicker {
  0%, 100% { text-shadow: 0 0 50px rgba(154, 37, 34, 0.24), 0 6px 0 rgba(24, 4, 4, 0.35); }
  50% { text-shadow: 0 0 70px rgba(192, 47, 40, 0.4), 0 6px 0 rgba(24, 4, 4, 0.35); }
}

.result-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  margin: 29px auto 5px;
  padding: 16px 0;
  border-top: 1px solid rgba(207, 175, 119, 0.15);
  border-bottom: 1px solid rgba(207, 175, 119, 0.15);
}

.result-grid div {
  padding: 0 8px;
}

.result-grid div + div {
  border-left: 1px solid rgba(207, 175, 119, 0.12);
}

.result-grid span {
  display: block;
  margin-bottom: 6px;
  font-family: var(--serif);
  font-size: 8px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: rgba(201, 190, 170, 0.38);
}

.result-grid b {
  font-family: var(--serif);
  font-size: 20px;
  font-weight: 500;
  color: rgba(235, 219, 190, 0.9);
  letter-spacing: 0.04em;
}

.victory-screen {
  background:
    radial-gradient(ellipse at 50% 48%, rgba(104, 58, 17, 0.34) 0%, rgba(20, 11, 6, 0.9) 48%, rgba(2, 3, 5, 0.97) 100%),
    rgba(2, 3, 5, 0.9);
}

.victory-title {
  font-size: clamp(48px, 7.2vw, 88px);
  color: #edc37c;
  text-shadow: 0 0 55px rgba(237, 167, 74, 0.38), 0 6px 0 rgba(40, 21, 7, 0.35);
}

.eyebrow.gold {
  color: rgba(236, 187, 106, 0.92);
}

.victory-screen .result-grid b {
  color: var(--gold-bright);
}

.fatal-error {
  display: none;
  position: absolute;
  inset: auto 20px 20px;
  z-index: 90;
  padding: 15px;
  color: #ffd7cf;
  background: rgba(80, 13, 13, 0.9);
  font-family: monospace;
}

.fatal-error.is-visible {
  display: block;
}

/* ------- Responsive ------- */

@media (max-width: 760px) {
  .title-screen {
    align-items: flex-end;
    justify-content: flex-start;
    padding: max(24px, env(safe-area-inset-top)) 24px max(34px, calc(env(safe-area-inset-bottom) + 24px));
    background:
      linear-gradient(180deg, rgba(3, 5, 8, 0.18) 0%, rgba(3, 5, 8, 0.25) 34%, rgba(3, 5, 8, 0.87) 64%, rgba(3, 5, 8, 0.97) 100%);
  }

  .title-inner {
    width: 100%;
  }

  .logo {
    font-size: clamp(64px, 20vw, 104px);
  }

  .tagline {
    margin-top: 21px;
    font-size: 20px;
  }

  .ornate-btn {
    margin-top: 27px;
  }

  .title-controls {
    gap: 14px;
    flex-wrap: wrap;
    margin-top: 23px;
    padding-top: 15px;
  }

  .title-foot {
    display: none;
  }

  .title-screen .eyebrow {
    margin-bottom: 15px;
  }

  .boss-hud {
    top: max(73px, calc(env(safe-area-inset-top) + 62px));
    width: calc(100vw - 32px);
  }

  .boss-heading {
    flex-direction: column;
    align-items: center;
    gap: 2px;
    margin-bottom: 6px;
  }

  .boss-heading h2 {
    font-size: 11px;
    text-align: center;
  }

  .hud {
    padding-left: max(18px, calc(env(safe-area-inset-left) + 14px));
    padding-right: max(18px, calc(env(safe-area-inset-right) + 14px));
  }

  .flask {
    width: 22px;
    height: 28px;
  }

  .run-stats {
    font-size: 10px;
  }

  .hint {
    display: none;
  }

  .cast-btn {
    width: 75px;
    height: 75px;
    right: max(20px, calc(env(safe-area-inset-right) + 16px));
    bottom: max(26px, calc(env(safe-area-inset-bottom) + 20px));
  }

  .banner {
    top: 21%;
  }

  .result-grid {
    margin-top: 21px;
  }

  .result-grid b {
    font-size: 17px;
  }

  .modal-copy {
    font-size: 17px;
  }

  .death-title {
    font-size: clamp(54px, 17vw, 84px);
  }
}

@media (max-width: 390px) {
  .title-controls i {
    display: none;
  }

  .title-controls {
    gap: 10px 18px;
  }

  .record {
    margin-top: 16px;
  }

  .tagline {
    font-size: 18px;
  }

  .result-grid span {
    font-size: 7px;
    letter-spacing: 0.13em;
  }

  .modal-copy {
    margin-top: 14px;
  }
}

@media (max-height: 660px) and (min-width: 761px) {
  .logo {
    font-size: clamp(60px, 8.4vw, 108px);
  }

  .tagline {
    margin-top: 19px;
  }

  .ornate-btn {
    margin-top: 23px;
  }

  .title-controls {
    margin-top: 18px;
    padding-top: 12px;
  }

  .title-foot {
    display: none;
  }

  .boss-hud {
    top: 64px;
  }
}

@media (hover: none) and (pointer: coarse) {
  .hint {
    display: none;
  }

  .cast-btn {
    opacity: 0.88;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

'use strict';

// ---------------------------------------------------------------------------
// Hollowwing — shared setup, helpers, audio
// ---------------------------------------------------------------------------

const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d', { alpha: false });
const gameEl = document.getElementById('game');

const ui = {
  hud: document.getElementById('hud'),
  flasks: [...document.querySelectorAll('.flask')],
  souls: document.getElementById('soulCount'),
  distance: document.getElementById('distanceCount'),
  bossHud: document.getElementById('bossHud'),
  bossName: document.getElementById('bossName'),
