'use strict';

// ---------------------------------------------------------------------------
// World entities and player rendering
// ---------------------------------------------------------------------------

function drawObstacle(o, t) {
  const topEdge = o.gapY - o.gapH * 0.5;
  const bottomEdge = o.gapY + o.gapH * 0.5;

  drawCrag(o.x, 0, o.w, topEdge, true, o.seed, t);
  drawCrag(o.x, bottomEdge, o.w, H - bottomEdge, false, o.seed + 17.3, t);

  // A pale seam of soul-light inside the rock.
  const seam = ctx.createLinearGradient(o.x, 0, o.x + o.w, 0);
  seam.addColorStop(0, 'rgba(105, 184, 188, 0.02)');
  seam.addColorStop(0.55, 'rgba(105, 184, 188, 0.075)');
  seam.addColorStop(1, 'rgba(40, 73, 77, 0.01)');
  ctx.strokeStyle = seam;
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(o.x + o.w * 0.35, topEdge - 38);
  ctx.lineTo(o.x + o.w * 0.62, topEdge - 10);
  ctx.moveTo(o.x + o.w * 0.42, bottomEdge + 20);
  ctx.lineTo(o.x + o.w * 0.7, bottomEdge + 52);
  ctx.stroke();

  if (o.passed) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.fillStyle = 'rgba(130, 215, 220, 0.05)';
    ctx.fillRect(o.x + o.w - 2, topEdge, 2, o.gapH);
    ctx.restore();
  }
}

function drawCrag(x, y, w, h, ceiling, seed, t) {
  const edge = ceiling ? y + h : y;
  const dir = ceiling ? -1 : 1; // direction away from the gap
  const pts = [];
  const count = 7;
  for (let i = 0; i <= count; i++) {
    const u = i / count;
    const j = hash01(seed * 11.7 + i * 3.13);
    const edgeOffset = (hash01(seed * 5.1 + i * 1.79) - 0.42) * 22;
    pts.push({
      x: x + u * w,
      y: edge + edgeOffset + (i === 1 || i === 5 ? dir * (12 + j * 26) : 0),
    });
  }

  const grad = ctx.createLinearGradient(x, y, x + w * 0.55, y + h);
  grad.addColorStop(0, ceiling ? '#161c23' : '#131920');
  grad.addColorStop(0.45, '#0d1218');
  grad.addColorStop(1, '#06090d');

  ctx.beginPath();
  if (ceiling) {
    ctx.moveTo(x - 8, y - 8);
    ctx.lineTo(x + w + 8, y - 8);
    ctx.lineTo(x + w + 8, edge - 10);
  } else {
    ctx.moveTo(x - 8, y + h + 8);
    ctx.lineTo(x + w + 8, y + h + 8);
    ctx.lineTo(x + w + 8, edge + 10);
  }
  for (let i = pts.length - 1; i >= 0; i--) ctx.lineTo(pts[i].x, pts[i].y);
  if (ceiling) ctx.lineTo(x - 8, edge - 10);
  else ctx.lineTo(x - 8, edge + 10);
  ctx.closePath();
  ctx.fillStyle = grad;
  ctx.fill();

  // Edge light facing the open gap.
  ctx.strokeStyle = 'rgba(105, 137, 141, 0.17)';
  ctx.lineWidth = 1.4;
  ctx.beginPath();
  ctx.moveTo(pts[0].x, pts[0].y);
  for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i].x, pts[i].y);
  ctx.stroke();

  // Rock cracks.
  ctx.save();
  ctx.beginPath();
  ctx.rect(x + 2, ceiling ? y : y, w - 4, h - 2);
  ctx.clip();
  for (let i = 0; i < 3; i++) {
    const sx = x + w * (0.18 + hash01(seed * 3.3 + i * 4.1) * 0.64);
    const sy = edge + dir * (18 + hash01(seed * 4.4 + i) * Math.max(28, h * 0.35));
    const ex = sx + (hash01(seed + i * 9.3) - 0.5) * 34;
    const ey = sy + dir * (28 + hash01(seed * 7.1 + i) * 55);
    ctx.strokeStyle = i === 0 ? 'rgba(0, 0, 0, 0.52)' : 'rgba(0, 0, 0, 0.32)';
    ctx.lineWidth = i === 0 ? 1.7 : 1;
    ctx.beginPath();
    ctx.moveTo(sx, sy);
    ctx.quadraticCurveTo(sx + (ex - sx) * 0.25, sy + (ey - sy) * 0.62, ex, ey);
    if (i === 0) {
      ctx.lineTo(ex + 7, ey - dir * 13);
    }
    ctx.stroke();
  }
  ctx.restore();

  // Glowing cave lichen on a few tips.
  const lichenCount = hash01(seed * 2.2) > 0.45 ? 2 : 1;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  for (let i = 0; i < lichenCount; i++) {
    const p = pts[1 + ((i * 3 + 1) % (pts.length - 2))];
    const lx = p.x + (hash01(seed + i * 5) - 0.5) * w * 0.28;
    const ly = p.y - dir * (4 + hash01(seed + i * 6.1) * 12);
    const pulse = 0.5 + Math.sin(t * 1.8 + seed + i * 2.7) * 0.35;
    const glow = ctx.createRadialGradient(lx, ly, 0, lx, ly, 13);
    glow.addColorStop(0, `rgba(123, 225, 223, ${0.26 * pulse})`);
    glow.addColorStop(1, 'rgba(70, 170, 180, 0)');
    ctx.fillStyle = glow;
    ctx.beginPath();
    ctx.arc(lx, ly, 13, 0, TAU);
    ctx.fill();
    ctx.fillStyle = `rgba(151, 235, 230, ${0.4 + pulse * 0.45})`;
    ctx.beginPath();
    ctx.arc(lx, ly, 1.2 + pulse, 0, TAU);
    ctx.fill();
  }
  ctx.restore();
}

function drawPickup(p, t) {
  const y = p.baseY + Math.sin(t * 2.1 + p.phase) * 6;
  if (p.kind === 'estus') {
    ctx.save();
    ctx.translate(p.x, y);
    ctx.globalCompositeOperation = 'lighter';
    const glow = ctx.createRadialGradient(0, 0, 0, 0, 0, 34);
    glow.addColorStop(0, 'rgba(255, 195, 92, 0.43)');
    glow.addColorStop(0.4, 'rgba(255, 126, 42, 0.15)');
    glow.addColorStop(1, 'rgba(180, 55, 10, 0)');
    ctx.fillStyle = glow;
    ctx.beginPath();
    ctx.arc(0, 0, 34, 0, TAU);
    ctx.fill();
    ctx.globalCompositeOperation = 'source-over';

    ctx.rotate(Math.sin(t * 1.3 + p.phase) * 0.1);
    ctx.fillStyle = 'rgba(221, 170, 87, 0.94)';
    roundRectPath(ctx, -5.5, -6, 11, 15, 3.4);
    ctx.fill();
    ctx.fillStyle = '#9a8b69';
    ctx.fillRect(-2, -10, 4, 5);
    ctx.fillStyle = '#fff0b8';
    ctx.beginPath();
    ctx.ellipse(0, 0, 2.4, 4.2, 0, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = 'rgba(255, 237, 189, 0.6)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(0, 1, 9 + Math.sin(t * 3 + p.phase) * 1.2, 0, TAU);
    ctx.stroke();
    ctx.restore();
    return;
  }

  ctx.save();
  ctx.translate(p.x, y);
  ctx.globalCompositeOperation = 'lighter';
  const glow = ctx.createRadialGradient(0, 0, 0, 0, 0, 27);
  glow.addColorStop(0, 'rgba(145, 242, 255, 0.4)');
  glow.addColorStop(0.42, 'rgba(66, 184, 224, 0.13)');
  glow.addColorStop(1, 'rgba(35, 115, 170, 0)');
  ctx.fillStyle = glow;
  ctx.beginPath();
  ctx.arc(0, 0, 27, 0, TAU);
  ctx.fill();

  const bob = Math.sin(t * 1.8 + p.phase);
  ctx.rotate(t * 0.9 + p.phase);
  ctx.fillStyle = 'rgba(157, 245, 255, 0.88)';
  ctx.beginPath();
  ctx.moveTo(0, -7 - bob);
  ctx.lineTo(5, 0);
  ctx.lineTo(0, 7 + bob);
  ctx.lineTo(-5, 0);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = '#f2ffff';
  ctx.beginPath();
  ctx.arc(0, 0, 2.1, 0, TAU);
  ctx.fill();
  ctx.restore();

  ctx.save();
  ctx.translate(p.x, y);
  ctx.strokeStyle = 'rgba(122, 226, 241, 0.28)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.ellipse(0, 0, 14, 6, Math.sin(t + p.phase) * 0.4, 0, TAU);
  ctx.stroke();
  ctx.restore();
}

function drawPlayer(p, t) {
  if (!p) return;
  const s = G.metrics.scale;
  const blink = p.iframes > 0 && Math.floor(p.iframes * 18) % 2 === 0;
  const flap = p.wing;

  ctx.save();
  ctx.translate(p.x, p.y);
  ctx.rotate(p.rot);
  ctx.globalAlpha = blink ? 0.38 : 1;

  // Ember cloak — a pair of tattered, wing-like feathers.
  const spread = 4 + flap * 15 + Math.sin(t * 7.4) * 1.6;
  const wingGrad = ctx.createLinearGradient(-42 * s, -20 * s, 2, 14 * s);
  wingGrad.addColorStop(0, 'rgba(90, 35, 30, 0.72)');
  wingGrad.addColorStop(0.55, 'rgba(55, 24, 25, 0.92)');
  wingGrad.addColorStop(1, 'rgba(22, 14, 17, 0.96)');

  ctx.fillStyle = wingGrad;
  ctx.beginPath();
  ctx.moveTo(-4 * s, -8 * s);
  ctx.bezierCurveTo(-16 * s, (-30 - spread) * s, (-36 - spread) * s, -24 * s, (-48 - spread * 0.7) * s, -9 * s);
  ctx.lineTo((-39 - spread * 0.5) * s, -12 * s);
  ctx.lineTo((-45 - spread * 0.3) * s, 1 * s);
  ctx.lineTo((-33 - spread * 0.2) * s, -3 * s);
  ctx.lineTo((-36 - spread * 0.1) * s, 11 * s);
  ctx.lineTo((-25 - spread * 0.1) * s, 3 * s);
  ctx.lineTo((-24 - spread * 0.1) * s, 16 * s);
  ctx.lineTo(-12 * s, 8 * s);
  ctx.closePath();
  ctx.fill();

  ctx.fillStyle = 'rgba(130, 48, 34, 0.46)';
  ctx.beginPath();
  ctx.moveTo(-9 * s, -12 * s);
  ctx.bezierCurveTo(-24 * s, (-27 - spread * 0.8) * s, (-38 - spread * 0.4) * s, -17 * s, (-42 - spread * 0.25) * s, -5 * s);
  ctx.lineTo(-29 * s, -8 * s);
  ctx.lineTo(-31 * s, 4 * s);
  ctx.lineTo(-20 * s, -1 * s);
  ctx.closePath();
  ctx.fill();

  // Torn trailing cloth.
  ctx.fillStyle = 'rgba(38, 17, 19, 0.93)';
  ctx.beginPath();
  ctx.moveTo(-7 * s, 8 * s);
  ctx.bezierCurveTo(-15 * s, 18 * s, (-23 - flap * 4) * s, 26 * s, (-31 - flap * 3) * s, 35 * s);
  ctx.lineTo((-19 - flap * 2) * s, 29 * s);
  ctx.lineTo((-19 - flap * 2) * s, 39 * s);
  ctx.lineTo(-8 * s, 28 * s);
  ctx.lineTo(-2 * s, 19 * s);
  ctx.closePath();
  ctx.fill();

  // Body and cloak latches.
  ctx.fillStyle = '#1c2228';
  roundRectPath(ctx, -9 * s, -11 * s, 22 * s, 27 * s, 7 * s);
  ctx.fill();
  ctx.fillStyle = 'rgba(79, 101, 105, 0.35)';
  roundRectPath(ctx, -6 * s, -8 * s, 14 * s, 18 * s, 5 * s);
  ctx.fill();
  ctx.strokeStyle = 'rgba(101, 154, 158, 0.46)';
  ctx.lineWidth = Math.max(1, 1.1 * s);
  ctx.beginPath();
  ctx.moveTo(-4 * s, -6 * s);
  ctx.lineTo(8 * s, -1 * s);
  ctx.lineTo(4 * s, 8 * s);
  ctx.stroke();

  // Belt and shoulder plate.
  ctx.fillStyle = '#0b0d10';
  ctx.fillRect(-9 * s, 8 * s, 22 * s, 3 * s);
  ctx.fillStyle = '#313b40';
  ctx.beginPath();
  ctx.ellipse(8 * s, -7 * s, 7 * s, 4.5 * s, -0.28, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#11161a';
  ctx.beginPath();
  ctx.moveTo(2 * s, -10 * s);
  ctx.lineTo(14 * s, -11 * s);
  ctx.lineTo(16 * s, -4 * s);
  ctx.lineTo(5 * s, -3 * s);
  ctx.closePath();
  ctx.fill();

  // Sword arm and blade.
  const castGlow = p.castAnim;
  ctx.strokeStyle = '#171b1e';
  ctx.lineWidth = Math.max(2.8, 3.4 * s);
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(8 * s, 1 * s);
  ctx.lineTo(18 * s, 6 * s);
  ctx.stroke();
  ctx.strokeStyle = castGlow > 0 ? 'rgba(174, 244, 255, 0.95)' : '#8c9898';
  ctx.lineWidth = Math.max(1.4, 1.8 * s);
  ctx.beginPath();
  ctx.moveTo(17 * s, 5 * s);
  ctx.lineTo(39 * s, 15 * s);
  ctx.stroke();
  if (castGlow > 0) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const g = ctx.createLinearGradient(18 * s, 6 * s, 40 * s, 16 * s);
    g.addColorStop(0, `rgba(102, 230, 255, ${0.18 * castGlow})`);
    g.addColorStop(1, `rgba(197, 250, 255, ${0.65 * castGlow})`);
    ctx.strokeStyle = g;
    ctx.lineWidth = 5 * s;
    ctx.beginPath();
    ctx.moveTo(17 * s, 5 * s);
    ctx.lineTo(41 * s, 16 * s);
    ctx.stroke();
    ctx.restore();
  }
  ctx.strokeStyle = '#3e3330';
  ctx.lineWidth = Math.max(2, 2.2 * s);
  ctx.beginPath();
  ctx.moveTo(16 * s, 2 * s);
  ctx.lineTo(19 * s, 9 * s);
  ctx.stroke();

  // Head and horned helm.
  ctx.fillStyle = '#20272c';
  ctx.beginPath();
  ctx.ellipse(7 * s, -16 * s, 9.4 * s, 8.4 * s, -0.12, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#13181c';
  ctx.beginPath();
  ctx.moveTo(7 * s, -24 * s);
  ctx.quadraticCurveTo(13 * s, -29 * s, 18 * s, -23 * s);
  ctx.lineTo(16 * s, -14 * s);
  ctx.lineTo(8 * s, -12 * s);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = '#4a5559';
  ctx.lineWidth = Math.max(1, 1.1 * s);
  ctx.beginPath();
  ctx.moveTo(10 * s, -21 * s);
  ctx.lineTo(15 * s, -19 * s);
  ctx.stroke();

  // Curving horns.
  ctx.strokeStyle = '#79756a';
  ctx.lineWidth = Math.max(1.5, 2 * s);
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(2 * s, -22 * s);
  ctx.quadraticCurveTo(-5 * s, -31 * s, -12 * s, -28 * s);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(7 * s, -24 * s);
  ctx.quadraticCurveTo(5 * s, -32 * s, 0, -35 * s);
  ctx.stroke();

  // Eyes.
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const eye = ctx.createRadialGradient(12.5 * s, -17 * s, 0, 12.5 * s, -17 * s, 7 * s);
  eye.addColorStop(0, 'rgba(206, 255, 255, 0.98)');
  eye.addColorStop(0.28, 'rgba(89, 225, 247, 0.82)');
  eye.addColorStop(1, 'rgba(40, 126, 160, 0)');
  ctx.fillStyle = eye;
  ctx.beginPath();
  ctx.arc(12.5 * s, -17 * s, 7 * s, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#eaffff';
  ctx.beginPath();
  ctx.ellipse(12.7 * s, -17 * s, 1.9 * s, 1.1 * s, 0, 0, TAU);
  ctx.fill();
  ctx.restore();

  ctx.restore();

  // A warm, barely-there rim light from the cave fires.
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.strokeStyle = 'rgba(238, 150, 79, 0.15)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.arc(p.x, p.y, 25 * s, -Math.PI * 0.85, -Math.PI * 0.18);
  ctx.stroke();
  ctx.restore();
}

function drawBolt(b, t) {
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const speed = Math.hypot(b.vx, b.vy) || 1;
  const tx = b.x - (b.vx / speed) * 28;
  const ty = b.y - (b.vy / speed) * 28;
  const trail = ctx.createLinearGradient(b.x, b.y, tx, ty);
  trail.addColorStop(0, 'rgba(170, 247, 255, 0.8)');
  trail.addColorStop(0.35, 'rgba(84, 204, 239, 0.42)');
  trail.addColorStop(1, 'rgba(54, 142, 195, 0)');
  ctx.strokeStyle = trail;
  ctx.lineWidth = 4;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(b.x, b.y);
  ctx.lineTo(tx, ty);
  ctx.stroke();

  const glow = ctx.createRadialGradient(b.x, b.y, 0, b.x, b.y, 15);
  glow.addColorStop(0, 'rgba(238, 255, 255, 1)');
  glow.addColorStop(0.25, 'rgba(125, 231, 255, 0.8)');
  glow.addColorStop(1, 'rgba(48, 136, 190, 0)');
  ctx.fillStyle = glow;
  ctx.beginPath();
  ctx.arc(b.x, b.y, 15, 0, TAU);
  ctx.fill();

  ctx.translate(b.x, b.y);
  ctx.rotate(Math.atan2(b.vy, b.vx));
  ctx.fillStyle = '#eaffff';
  ctx.beginPath();
  ctx.moveTo(8, 0);
  ctx.lineTo(-2, 3.4);
  ctx.lineTo(-8, 0);
  ctx.lineTo(-2, -3.4);
  ctx.closePath();
  ctx.fill();
  ctx.restore();
}

function drawProjectile(p, t) {
  const r = p.r;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';

  const glow = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, r * 3.6);
  glow.addColorStop(0, p.core || 'rgba(255, 240, 205, 0.98)');
  glow.addColorStop(0.26, p.color || 'rgba(255, 150, 74, 0.72)');
  glow.addColorStop(1, 'rgba(90, 25, 8, 0)');
  ctx.fillStyle = glow;
  ctx.beginPath();
  ctx.arc(p.x, p.y, r * 3.6, 0, TAU);
  ctx.fill();

  if (p.kind === 'ember') {
    const speed = Math.hypot(p.vx, p.vy) || 1;
    const tx = p.x - p.vx / speed * r * 4.2;
    const ty = p.y - p.vy / speed * r * 4.2;
    const tail = ctx.createLinearGradient(p.x, p.y, tx, ty);
    tail.addColorStop(0, p.color || 'rgba(255, 148, 58, 0.9)');
    tail.addColorStop(1, 'rgba(135, 31, 4, 0)');
    ctx.strokeStyle = tail;
    ctx.lineWidth = r * 1.55;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(p.x, p.y);
    ctx.lineTo(tx, ty);
    ctx.stroke();
  }

  ctx.translate(p.x, p.y);
  ctx.rotate(p.rot || 0);
  ctx.fillStyle = p.color || '#ff9d57';
  ctx.beginPath();
  ctx.arc(0, 0, r, 0, TAU);
  ctx.fill();
  ctx.fillStyle = p.core || '#fff0c5';
  ctx.beginPath();
  ctx.arc(-r * 0.16, -r * 0.16, r * 0.48, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = 'rgba(255, 247, 220, 0.55)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.arc(0, 0, r + 2.5 + Math.sin(t * 8 + p.phase) * 0.8, 0, TAU);
  ctx.stroke();
  ctx.restore();
}

function drawBeam(b, t) {
  const life = clamp(1 - b.t / b.life, 0, 1);
  const alpha = life < 0.2 ? life / 0.2 : 1;
  const thickness = b.width * (0.7 + Math.sin(t * 48) * 0.12);
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const grad = ctx.createLinearGradient(0, b.y - thickness * 2, 0, b.y + thickness * 2);
  grad.addColorStop(0, 'rgba(255, 104, 42, 0)');
  grad.addColorStop(0.25, `rgba(255, 100, 38, ${0.25 * alpha})`);
  grad.addColorStop(0.5, `rgba(255, 241, 202, ${0.95 * alpha})`);
  grad.addColorStop(0.75, `rgba(255, 100, 38, ${0.25 * alpha})`);
  grad.addColorStop(1, 'rgba(255, 104, 42, 0)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, b.y - thickness * 2, b.x2, thickness * 4);

  ctx.strokeStyle = `rgba(255, 250, 233, ${0.9 * alpha})`;
  ctx.lineWidth = Math.max(2, thickness * 0.35);
  ctx.beginPath();
  ctx.moveTo(0, b.y);
  ctx.lineTo(b.x2, b.y);
  ctx.stroke();
  ctx.restore();
}

function drawParticles() {
  for (const p of G.particles) {
    const life = p.life / p.maxLife;
    const alpha = clamp(life, 0, 1) * p.alpha;
    if (alpha <= 0.005) continue;
    if (p.glow) {
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      ctx.fillStyle = p.color.replace('ALPHA', alpha.toFixed(3));
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.size * (0.5 + life * 0.8), 0, TAU);
      ctx.fill();
      ctx.restore();
    } else {
      ctx.save();
      ctx.globalAlpha = alpha;
      ctx.fillStyle = p.color;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.size * (0.55 + life * 0.65), 0, TAU);
      ctx.fill();
      ctx.restore();
    }
  }
}

function drawFloaters() {
  ctx.save();
  ctx.textAlign = 'center';
  for (const f of G.floaters) {
    const life = f.life / f.maxLife;
    ctx.globalAlpha = clamp(life, 0, 1);
    ctx.font = `500 ${f.size}px "Cinzel", serif`;
    ctx.fillStyle = f.color;
    ctx.shadowColor = f.shadow || f.color;
    ctx.shadowBlur = 8;
    ctx.fillText(f.text, f.x, f.y);
  }
  ctx.restore();
}

function drawPostEffects(t) {
  if (G.hurtFlash > 0) {
    const a = G.hurtFlash;
    const hurt = ctx.createRadialGradient(W * 0.5, H * 0.5, Math.min(W, H) * 0.22, W * 0.5, H * 0.5, Math.max(W, H) * 0.72);
    hurt.addColorStop(0, 'rgba(90, 0, 0, 0)');
    hurt.addColorStop(0.65, `rgba(123, 12, 10, ${0.18 * a})`);
    hurt.addColorStop(1, `rgba(156, 20, 14, ${0.56 * a})`);
    ctx.fillStyle = hurt;
    ctx.fillRect(0, 0, W, H);
  }

  if (G.healFlash > 0) {
    const a = G.healFlash;
    const heal = ctx.createRadialGradient(W * 0.5, H * 0.5, 0, W * 0.5, H * 0.5, Math.max(W, H) * 0.72);
    heal.addColorStop(0, `rgba(255, 208, 123, ${0.16 * a})`);
    heal.addColorStop(0.5, 'rgba(219, 140, 48, 0)');
    heal.addColorStop(1, `rgba(118, 57, 17, ${0.24 * a})`);
    ctx.fillStyle = heal;
    ctx.fillRect(0, 0, W, H);
  }

  if (G.flash > 0) {
    ctx.save();
    ctx.globalAlpha = G.flash;
    ctx.fillStyle = G.flashColor;
    ctx.fillRect(0, 0, W, H);
    ctx.restore();
  }

  if (G.lowHealth > 0) {
    const pulse = 0.35 + Math.sin(t * 4.2) * 0.18;
    const low = ctx.createRadialGradient(W * 0.5, H * 0.5, Math.min(W, H) * 0.32, W * 0.5, H * 0.5, Math.max(W, H) * 0.74);
    low.addColorStop(0, 'rgba(60, 0, 0, 0)');
    low.addColorStop(1, `rgba(126, 14, 12, ${0.34 * pulse * G.lowHealth})`);
    ctx.fillStyle = low;
    ctx.fillRect(0, 0, W, H);
  }
}

'use strict';

// ---------------------------------------------------------------------------
// The three keepers
// ---------------------------------------------------------------------------

function drawBoss(b, t) {
  if (!b) return;
  let alpha = 1;
  if (b.dead) alpha = clamp(1 - b.deathT / 2.2, 0, 1);
  if (b.type === 'bellwarden') drawBossBellwarden(b, alpha);
  else if (b.type === 'choir') drawBossChoir(b, alpha);
  else drawBossCinder(b, alpha);
  if (!b.dead) drawBossTelegraph(b, t);
}

function drawBossAuraLocal(b, color, radius) {
  const intensity = b.windup ? 0.26 : 0.12;
  const phase = b.phase2 ? 1.35 : 1;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const g = ctx.createRadialGradient(0, -10, 0, 0, -10, radius);
  g.addColorStop(0, color.replace('ALPHA', (intensity * phase).toFixed(3)));
  g.addColorStop(0.38, color.replace('ALPHA', (intensity * 0.36 * phase).toFixed(3)));
  g.addColorStop(1, color.replace('ALPHA', '0'));
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(0, -10, radius, 0, TAU);
  ctx.fill();
  ctx.restore();
}

function bossFlashOverlay(b) {
  if (!b.flash) return;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const g = ctx.createRadialGradient(0, -10, 0, 0, -10, 115);
  g.addColorStop(0, `rgba(235, 255, 255, ${0.9 * b.flash})`);
  g.addColorStop(0.42, `rgba(143, 233, 255, ${0.42 * b.flash})`);
  g.addColorStop(1, 'rgba(70, 155, 210, 0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(0, -10, 115, 0, TAU);
  ctx.fill();
  ctx.restore();
}

// ---------------------------------------------------------------------------
// Bellwarden of the Deep
// ---------------------------------------------------------------------------

function drawBossBellwarden(b, alpha = 1) {
  const T = b.t;
  const flap = Math.sin(T * 2.3) * 10;
  const breathe = Math.sin(T * 1.5) * 2.2;

  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.translate(b.x, b.y);
  ctx.scale(b.scale, b.scale);
  drawBossAuraLocal(b, 'rgba(247, 167, 82, ALPHA)', 178);

  // Wings.
  const wingGrad = ctx.createLinearGradient(-100, -80, 20, 55);
  wingGrad.addColorStop(0, '#252a2d');
  wingGrad.addColorStop(0.55, '#151a1d');
  wingGrad.addColorStop(1, '#0b0e11');

  ctx.fillStyle = wingGrad;
  ctx.beginPath();
  ctx.moveTo(-18, -16 + breathe);
  ctx.bezierCurveTo(-65, -72 - flap, -118, -78 - flap * 0.4, -142, -39 + flap * 0.2);
  ctx.lineTo(-117, -40 + flap * 0.2);
  ctx.lineTo(-127, -10 + flap * 0.25);
  ctx.lineTo(-97, -13 + flap * 0.2);
  ctx.lineTo(-102, 17 + flap * 0.2);
  ctx.lineTo(-73, 3);
  ctx.lineTo(-63, 25);
  ctx.lineTo(-43, 6);
  ctx.closePath();
  ctx.fill();

  ctx.beginPath();
  ctx.moveTo(18, -18 + breathe);
  ctx.bezierCurveTo(49, -68 - flap * 0.6, 92, -77 + flap * 0.4, 115, -38 + flap * 0.15);
  ctx.lineTo(97, -35);
  ctx.lineTo(103, -8 + flap * 0.2);
  ctx.lineTo(77, -12);
  ctx.lineTo(80, 17);
  ctx.lineTo(56, 2);
  ctx.lineTo(42, 23);
  ctx.lineTo(25, 0);
  ctx.closePath();
  ctx.fill();

  // Wing bones.
  ctx.strokeStyle = 'rgba(110, 117, 113, 0.26)';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(-28, -20);
  ctx.quadraticCurveTo(-82, -58 - flap * 0.7, -136, -42 + flap * 0.2);
  ctx.moveTo(-28, -19);
  ctx.quadraticCurveTo(-66, -25, -103, 14 + flap * 0.2);
  ctx.moveTo(26, -20);
  ctx.quadraticCurveTo(70, -57 - flap * 0.4, 109, -39);
  ctx.stroke();

  // Legs.
  ctx.strokeStyle = '#1b2023';
  ctx.lineWidth = 12;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(-22, 32);
  ctx.quadraticCurveTo(-31, 57, -42, 68);
  ctx.moveTo(17, 34);
  ctx.quadraticCurveTo(30, 57, 25, 71);
  ctx.stroke();
  ctx.strokeStyle = '#353c3d';
  ctx.lineWidth = 3;
  for (let i = 0; i < 3; i++) {
    ctx.beginPath();
    ctx.moveTo(-42, 68);
    ctx.lineTo(-50 - i * 2, 75 + i * 2);
    ctx.moveTo(25, 71);
    ctx.lineTo(31 + i * 2, 77 + i * 2);
    ctx.stroke();
  }

  // Hunched torso.
  const body = ctx.createLinearGradient(-40, -55, 45, 73);
  body.addColorStop(0, '#3b4242');
  body.addColorStop(0.3, '#272e30');
  body.addColorStop(0.7, '#181e21');
  body.addColorStop(1, '#0b0e11');
  ctx.fillStyle = body;
  ctx.beginPath();
  ctx.moveTo(-38, -15 + breathe);
  ctx.bezierCurveTo(-51, 3, -47, 37, -27, 48);
  ctx.quadraticCurveTo(0, 62, 29, 48);
  ctx.bezierCurveTo(48, 33, 47, 0, 31, -19 + breathe);
  ctx.quadraticCurveTo(0, -35 + breathe, -38, -15 + breathe);
  ctx.closePath();
  ctx.fill();

  // Ribs and belly plates.
  ctx.strokeStyle = 'rgba(130, 141, 134, 0.2)';
  ctx.lineWidth = 1.3;
  for (let i = 0; i < 4; i++) {
    ctx.beginPath();
    ctx.ellipse(-1, 2 + i * 9, 27 - i * 3.5, 9, 0.02, 0.15, Math.PI - 0.15);
    ctx.stroke();
  }

  // Arms and claws.
  ctx.strokeStyle = '#1c2225';
  ctx.lineWidth = 13;
  ctx.beginPath();
  ctx.moveTo(-33, -7);
  ctx.quadraticCurveTo(-58, 8, -51, 31);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(31, -10);
  ctx.quadraticCurveTo(54, 7, 45, 33);
  ctx.stroke();
  ctx.strokeStyle = '#5d5e56';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(-51, 31);
  ctx.lineTo(-61, 39);
  ctx.moveTo(-51, 31);
  ctx.lineTo(-56, 43);
  ctx.moveTo(-51, 31);
  ctx.lineTo(-47, 42);
  ctx.moveTo(45, 33);
  ctx.lineTo(54, 41);
  ctx.moveTo(45, 33);
  ctx.lineTo(48, 45);
  ctx.stroke();

  // Chain and bell.
  const swing = Math.sin(T * 2.6) * 0.18 + (b.windup ? Math.sin(T * 34) * 0.1 : 0);
  const bellY = 48;
  const bellX = -14 + Math.sin(swing) * 20;
  ctx.strokeStyle = '#4c493f';
  ctx.lineWidth = 1.8;
  ctx.beginPath();
  ctx.moveTo(-16, 12);
  ctx.lineTo(bellX - 2, bellY - 8);
  ctx.stroke();
  ctx.save();
  ctx.translate(bellX, bellY);
  ctx.rotate(swing);
  const bellGrad = ctx.createLinearGradient(-16, -14, 16, 18);
  bellGrad.addColorStop(0, '#a88950');
  bellGrad.addColorStop(0.35, '#6e5634');
  bellGrad.addColorStop(1, '#2f271b');
  ctx.fillStyle = bellGrad;
  ctx.beginPath();
  ctx.moveTo(-12, -12);
  ctx.quadraticCurveTo(0, -22, 12, -12);
  ctx.quadraticCurveTo(14, 2, 17, 10);
  ctx.quadraticCurveTo(0, 17, -17, 10);
  ctx.quadraticCurveTo(-14, 2, -12, -12);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(210, 180, 117, 0.3)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(-14, 7);
  ctx.quadraticCurveTo(0, 12, 14, 7);
  ctx.stroke();
  ctx.fillStyle = '#ba985d';
  ctx.beginPath();
  ctx.arc(0, 14, 3, 0, TAU);
  ctx.fill();
  if (b.windup) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const bg = ctx.createRadialGradient(0, 0, 0, 0, 0, 55);
    bg.addColorStop(0, 'rgba(255, 199, 108, 0.3)');
    bg.addColorStop(1, 'rgba(255, 115, 35, 0)');
    ctx.fillStyle = bg;
    ctx.beginPath();
    ctx.arc(0, 0, 55, 0, TAU);
    ctx.fill();
    ctx.restore();
  }
  ctx.restore();

  // Head, facing left.
  const headY = -37 + breathe;
  ctx.save();
  ctx.translate(-43, headY);
  ctx.rotate(-0.05 + Math.sin(T * 1.4) * 0.02);
  const headGrad = ctx.createLinearGradient(-38, -24, 18, 24);
  headGrad.addColorStop(0, '#444b49');
  headGrad.addColorStop(0.45, '#282f30');
  headGrad.addColorStop(1, '#12171a');
  ctx.fillStyle = headGrad;
  ctx.beginPath();
  ctx.moveTo(0, -28);
  ctx.quadraticCurveTo(-20, -27, -29, -16);
  ctx.lineTo(-46, -10);
  ctx.lineTo(-39, 2);
  ctx.lineTo(-40, 9);
  ctx.lineTo(-24, 7);
  ctx.lineTo(-15, 17);
  ctx.lineTo(4, 11);
  ctx.quadraticCurveTo(19, -4, 0, -28);
  ctx.closePath();
  ctx.fill();

  // Jaw.
  ctx.fillStyle = '#181d1f';
  ctx.beginPath();
  ctx.moveTo(-37, 4);
  ctx.lineTo(-21, 9);
  ctx.lineTo(-25, 17);
  ctx.lineTo(-39, 12);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(190, 183, 156, 0.45)';
  ctx.lineWidth = 1.1;
  for (let i = 0; i < 4; i++) {
    ctx.beginPath();
    ctx.moveTo(-35 + i * 4, 6);
    ctx.lineTo(-34 + i * 4, 11);
    ctx.stroke();
  }

  // Horns.
  ctx.strokeStyle = '#757366';
  ctx.lineCap = 'round';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.moveTo(-7, -25);
  ctx.quadraticCurveTo(-4, -47, 10, -49);
  ctx.quadraticCurveTo(4, -37, 6, -28);
  ctx.stroke();
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(-23, -21);
  ctx.quadraticCurveTo(-38, -35, -47, -31);
  ctx.quadraticCurveTo(-36, -26, -30, -17);
  ctx.stroke();

  // Eyes.
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const eyePulse = 0.7 + Math.sin(T * 4.1) * 0.25;
  const eg = ctx.createRadialGradient(-30, -7, 0, -30, -7, 12);
  eg.addColorStop(0, `rgba(255, 230, 163, ${eyePulse})`);
  eg.addColorStop(0.25, `rgba(245, 143, 55, ${eyePulse * 0.9})`);
  eg.addColorStop(1, 'rgba(220, 79, 27, 0)');
  ctx.fillStyle = eg;
  ctx.beginPath();
  ctx.arc(-31, -7, 12, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#ffe0a0';
  ctx.beginPath();
  ctx.ellipse(-31, -7, 2.8, 1.4, -0.12, 0, TAU);
  ctx.fill();
  ctx.restore();

  // Cracks.
  ctx.strokeStyle = 'rgba(3, 4, 5, 0.55)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(-46, -17);
  ctx.lineTo(-35, -12);
  ctx.lineTo(-37, -2);
  ctx.stroke();
  ctx.restore();

  bossFlashOverlay(b);
  ctx.restore();
}

// ---------------------------------------------------------------------------
// The Rotten Choir
// ---------------------------------------------------------------------------

function drawBossChoir(b, alpha = 1) {
  const T = b.t;
  const breathe = Math.sin(T * 1.25) * 3.2;
  const pulse = 0.7 + Math.sin(T * 3.4) * 0.2;

  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.translate(b.x, b.y);
  ctx.scale(b.scale, b.scale);
  drawBossAuraLocal(b, 'rgba(98, 214, 241, ALPHA)', 196);

  // Tendrils and drowned robes.
  ctx.strokeStyle = '#152328';
  ctx.lineCap = 'round';
  for (let i = 0; i < 8; i++) {
    const baseX = -55 + i * 16;
    const sway = Math.sin(T * 1.1 + i * 0.8) * 8;
    ctx.lineWidth = 5 - (i % 3);
    ctx.beginPath();
    ctx.moveTo(baseX, 38);
    ctx.bezierCurveTo(baseX - 8, 70, baseX + sway, 98, baseX + sway * 1.5 - 9, 128);
    ctx.stroke();
  }

  // Halo.
  ctx.save();
  ctx.rotate(T * 0.08);
  ctx.strokeStyle = 'rgba(146, 234, 247, 0.23)';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(0, -69, 86, 0, TAU);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(89, 158, 170, 0.14)';
  ctx.lineWidth = 9;
  ctx.beginPath();
  ctx.arc(0, -69, 92, 0.1, 2.5);
  ctx.stroke();
  for (let i = 0; i < 10; i++) {
    const a = (i / 10) * TAU;
    const cx = Math.cos(a) * 86;
    const cy = -69 + Math.sin(a) * 86;
    ctx.fillStyle = '#c0baa1';
    ctx.beginPath();
    ctx.arc(cx, cy, 3.2, 0, TAU);
    ctx.fill();
    const fh = 5 + Math.sin(T * 6 + i) * 1.2;
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.fillStyle = 'rgba(255, 187, 96, 0.55)';
    ctx.beginPath();
    ctx.ellipse(cx, cy - 6, 2.1, fh, 0, 0, TAU);
    ctx.fill();
    ctx.restore();
  }
  ctx.restore();

  // Shoulder bones.
  ctx.fillStyle = '#2c3433';
  ctx.beginPath();
  ctx.ellipse(-56, 48, 24, 14, -0.25, 0, TAU);
  ctx.ellipse(52, 48, 24, 14, 0.25, 0, TAU);
  ctx.fill();

  // Skull cranium.
  const bone = ctx.createLinearGradient(-55, -90, 65, 56);
  bone.addColorStop(0, '#c5bea6');
  bone.addColorStop(0.28, '#9e9885');
  bone.addColorStop(0.62, '#716e62');
  bone.addColorStop(1, '#3e403c');
  ctx.fillStyle = bone;
  ctx.beginPath();
  ctx.moveTo(-11, -91 + breathe);
  ctx.bezierCurveTo(-53, -94 + breathe, -74, -62 + breathe, -66, -22);
  ctx.lineTo(-71, 8);
  ctx.bezierCurveTo(-63, 23, -47, 23, -41, 15);
  ctx.lineTo(-38, 42);
  ctx.quadraticCurveTo(-3, 62, 33, 41);
  ctx.lineTo(40, 16);
  ctx.bezierCurveTo(66, 7, 71, -21, 62, -47);
  ctx.bezierCurveTo(51, -82, 24, -94, -11, -91 + breathe);
  ctx.closePath();
  ctx.fill();

  // Cheek and jaw shadow.
  ctx.fillStyle = 'rgba(35, 39, 37, 0.72)';
  ctx.beginPath();
  ctx.moveTo(-37, 13);
  ctx.quadraticCurveTo(-18, 33, 3, 30);
  ctx.lineTo(8, 50);
  ctx.quadraticCurveTo(-17, 49, -35, 33);
  ctx.closePath();
  ctx.fill();

  // Open mouth.
  const mouth = ctx.createRadialGradient(-5, 29, 0, -5, 29, 42);
  mouth.addColorStop(0, `rgba(183, 247, 255, ${0.75 * pulse})`);
  mouth.addColorStop(0.35, 'rgba(55, 145, 168, 0.65)');
  mouth.addColorStop(1, 'rgba(7, 20, 24, 0.95)');
  ctx.fillStyle = mouth;
  ctx.beginPath();
  ctx.ellipse(-4, 29, 31, 19, -0.03, 0, TAU);
  ctx.fill();

  // Teeth.
  ctx.fillStyle = '#c7c0a8';
  for (let i = 0; i < 7; i++) {
    const tx = -28 + i * 7.3;
    ctx.beginPath();
    ctx.moveTo(tx, 12);
    ctx.lineTo(tx + 3.2, 22 + (i % 2) * 3);
    ctx.lineTo(tx + 6.3, 12);
    ctx.closePath();
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(tx + 1, 44);
    ctx.lineTo(tx + 3.8, 35 - (i % 2) * 2);
    ctx.lineTo(tx + 6.8, 44);
    ctx.closePath();
    ctx.fill();
  }

  // Eye sockets.
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const eyePositions = [
    [-32, -35, 12],
    [21, -39, 13],
    [-6, -67, 9],
  ];
  for (let i = 0; i < eyePositions.length; i++) {
    const [ex, ey, er] = eyePositions[i];
    const eg = ctx.createRadialGradient(ex, ey, 0, ex, ey, er * 2.5);
    eg.addColorStop(0, `rgba(223, 255, 255, ${0.95 * pulse})`);
    eg.addColorStop(0.25, 'rgba(92, 225, 244, 0.72)');
    eg.addColorStop(1, 'rgba(31, 116, 145, 0)');
    ctx.fillStyle = eg;
    ctx.beginPath();
    ctx.arc(ex, ey, er * 2.5, 0, TAU);
    ctx.fill();
    ctx.fillStyle = 'rgba(5, 14, 18, 0.9)';
    ctx.beginPath();
    ctx.ellipse(ex, ey, er * 0.62, er * 0.82, -0.1, 0, TAU);
    ctx.fill();
    ctx.fillStyle = '#d8ffff';
    ctx.beginPath();
    ctx.arc(ex - 1, ey, er * 0.16, 0, TAU);
    ctx.fill();
  }
  ctx.restore();

  // Nasal cavity.
  ctx.fillStyle = 'rgba(13, 18, 18, 0.88)';
  ctx.beginPath();
  ctx.moveTo(-7, 0);
  ctx.lineTo(4, -2);
  ctx.lineTo(9, 12);
  ctx.lineTo(-3, 15);
  ctx.closePath();
  ctx.fill();

  // Cracks and moss.
  ctx.strokeStyle = 'rgba(37, 42, 40, 0.6)';
  ctx.lineWidth = 1.4;
  ctx.beginPath();
  ctx.moveTo(45, -65);
  ctx.lineTo(31, -48);
  ctx.lineTo(38, -34);
  ctx.moveTo(-53, -47);
  ctx.lineTo(-44, -34);
  ctx.lineTo(-49, -18);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(92, 146, 136, 0.28)';
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.moveTo(31, -74);
  ctx.quadraticCurveTo(45, -56, 40, -42);
  ctx.stroke();

  // Small attending skulls.
  for (let i = 0; i < 3; i++) {
    const a = T * 0.28 + i * 2.1;
    const rx = Math.cos(a) * 103;
    const ry = -45 + Math.sin(a) * 28;
    ctx.save();
    ctx.translate(rx, ry);
    ctx.scale(0.55, 0.55);
    ctx.fillStyle = 'rgba(157, 151, 133, 0.68)';
    ctx.beginPath();
    ctx.arc(0, 0, 16, 0, TAU);
    ctx.fill();
    ctx.fillStyle = 'rgba(12, 18, 19, 0.9)';
    ctx.beginPath();
    ctx.arc(-6, -2, 4, 0, TAU);
    ctx.arc(7, -2, 4, 0, TAU);
    ctx.fill();
    ctx.fillStyle = '#9cebf6';
    ctx.beginPath();
    ctx.arc(-6, -2, 1.4, 0, TAU);
    ctx.arc(7, -2, 1.4, 0, TAU);
    ctx.fill();
    ctx.restore();
  }

  bossFlashOverlay(b);
  ctx.restore();
}

// ---------------------------------------------------------------------------
// Cinder Monarch
// ---------------------------------------------------------------------------

function drawBossCinder(b, alpha = 1) {
  const T = b.t;
  const breathe = Math.sin(T * 1.4) * 2.5;
  const flame = Math.sin(T * 6.8) * 6 + Math.sin(T * 11.2) * 3;
  const phase = b.phase2 ? 1.35 : 1;

  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.translate(b.x, b.y);
  ctx.scale(b.scale, b.scale);
  drawBossAuraLocal(b, 'rgba(255, 105, 40, ALPHA)', 200);

  // A cape of living fire.
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const cape = ctx.createLinearGradient(0, -30, 95, 80);
  cape.addColorStop(0, 'rgba(255, 202, 102, 0.52)');
  cape.addColorStop(0.32, 'rgba(239, 104, 34, 0.62)');
  cape.addColorStop(0.7, 'rgba(132, 31, 12, 0.38)');
  cape.addColorStop(1, 'rgba(45, 8, 2, 0)');
  ctx.fillStyle = cape;
  ctx.beginPath();
  ctx.moveTo(22, -39);
  ctx.bezierCurveTo(77, -58 - flame, 115, -31 - flame * 0.4, 126, 22 + flame * 0.5);
  ctx.bezierCurveTo(105, 12, 104, 48 + flame, 82, 38);
  ctx.bezierCurveTo(80, 74 + flame, 57, 59, 48, 89);
  ctx.bezierCurveTo(43, 67, 31, 75, 26, 53);
  ctx.bezierCurveTo(18, 61, 15, 42, 10, 30);
  ctx.closePath();
  ctx.fill();
  ctx.restore();

  // Lower smoke and legs.
  ctx.strokeStyle = '#0c0d10';
  ctx.lineWidth = 14;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(-22, 33);
  ctx.quadraticCurveTo(-34, 58, -29, 82);
  ctx.moveTo(16, 34);
  ctx.quadraticCurveTo(30, 61, 22, 85);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(198, 85, 38, 0.35)';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(-24, 43);
  ctx.lineTo(-31, 60);
  ctx.moveTo(20, 48);
  ctx.lineTo(27, 67);
  ctx.stroke();

  // Tattered skirt plates.
  ctx.fillStyle = '#131418';
  ctx.beginPath();
  ctx.moveTo(-30, 28);
  ctx.lineTo(28, 28);
  ctx.lineTo(36, 65);
  ctx.lineTo(18, 56);
  ctx.lineTo(8, 78);
  ctx.lineTo(-5, 58);
  ctx.lineTo(-20, 74);
  ctx.lineTo(-25, 52);
  ctx.lineTo(-38, 61);
  ctx.closePath();
  ctx.fill();

  // Torso armor.
  const armor = ctx.createLinearGradient(-44, -54, 40, 40);
  armor.addColorStop(0, '#313134');
  armor.addColorStop(0.32, '#1b1b1f');
  armor.addColorStop(0.75, '#101014');
  armor.addColorStop(1, '#07080a');
  ctx.fillStyle = armor;
  ctx.beginPath();
  ctx.moveTo(-35, -30 + breathe);
  ctx.quadraticCurveTo(-54, -12, -42, 14);
  ctx.quadraticCurveTo(-31, 34, 0, 39);
  ctx.quadraticCurveTo(34, 32, 43, 12);
  ctx.quadraticCurveTo(52, -15, 30, -34 + breathe);
  ctx.quadraticCurveTo(0, -46 + breathe, -35, -30 + breathe);
  ctx.closePath();
  ctx.fill();

  // Chest fissures.
  ctx.strokeStyle = `rgba(255, 113, 40, ${0.52 * phase})`;
  ctx.lineWidth = 2;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.beginPath();
  ctx.moveTo(-1, -22);
  ctx.lineTo(-8, -9);
  ctx.lineTo(3, 2);
  ctx.lineTo(-3, 18);
  ctx.moveTo(-28, -10);
  ctx.lineTo(-17, -2);
  ctx.lineTo(-21, 12);
  ctx.moveTo(24, -17);
  ctx.lineTo(17, -6);
  ctx.lineTo(25, 6);
  ctx.stroke();
  ctx.restore();

  // Pauldrons.
  ctx.fillStyle = '#18191d';
  ctx.beginPath();
  ctx.ellipse(-43, -23 + breathe, 20, 14, -0.3, 0, TAU);
  ctx.ellipse(39, -22 + breathe, 20, 14, 0.3, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = 'rgba(255, 123, 54, 0.24)';
  ctx.lineWidth = 1.3;
  ctx.beginPath();
  ctx.arc(-43, -23 + breathe, 16, 0.6, 2.3);
  ctx.arc(39, -22 + breathe, 16, -2.3, -0.6);
  ctx.stroke();

  // Left arm and claw.
  ctx.strokeStyle = '#141519';
  ctx.lineWidth = 12;
  ctx.beginPath();
  ctx.moveTo(-35, -10);
  ctx.quadraticCurveTo(-54, 10, -48, 32);
  ctx.stroke();
  ctx.fillStyle = '#2e2c29';
  ctx.beginPath();
  ctx.arc(-48, 34, 7, 0, TAU);
  ctx.fill();

  // Right arm and greatsword.
  ctx.strokeStyle = '#141519';
  ctx.lineWidth = 13;
  ctx.beginPath();
  ctx.moveTo(34, -13);
  ctx.quadraticCurveTo(50, 3, 50, 19);
  ctx.stroke();

  ctx.save();
  ctx.translate(48, 18);
  ctx.rotate(-0.18 + Math.sin(T * 1.2) * 0.02);
  const blade = ctx.createLinearGradient(0, 0, 100, 72);
  blade.addColorStop(0, '#a39678');
  blade.addColorStop(0.28, '#68645b');
  blade.addColorStop(1, '#24262a');
  ctx.fillStyle = blade;
  ctx.beginPath();
  ctx.moveTo(-3, 2);
  ctx.lineTo(85, 59);
  ctx.lineTo(94, 55);
  ctx.lineTo(100, 39);
  ctx.lineTo(10, -8);
  ctx.closePath();
  ctx.fill();
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.strokeStyle = `rgba(255, 119, 42, ${0.45 * phase})`;
  ctx.lineWidth = 2.5;
  ctx.beginPath();
  ctx.moveTo(14, -6);
  ctx.lineTo(91, 44);
  ctx.stroke();
  ctx.restore();
  ctx.strokeStyle = '#5f4b30';
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.moveTo(-1, -6);
  ctx.lineTo(9, 8);
  ctx.moveTo(3, 1);
  ctx.lineTo(13, -9);
  ctx.stroke();
  ctx.restore();

  // Head and horned crown.
  const hy = -55 + breathe;
  ctx.fillStyle = '#1a1b1f';
  ctx.beginPath();
  ctx.moveTo(-19, hy + 8);
  ctx.quadraticCurveTo(-18, hy - 19, 0, hy - 23);
  ctx.quadraticCurveTo(19, hy - 18, 20, hy + 8);
  ctx.lineTo(13, hy + 19);
  ctx.lineTo(-12, hy + 19);
  ctx.closePath();
  ctx.fill();

  // Crown spikes.
  ctx.fillStyle = '#5a4e3a';
  ctx.beginPath();
  ctx.moveTo(-16, hy - 13);
  ctx.lineTo(-22, hy - 32);
  ctx.lineTo(-9, hy - 20);
  ctx.lineTo(-2, hy - 42);
  ctx.lineTo(5, hy - 20);
  ctx.lineTo(16, hy - 34);
  ctx.lineTo(19, hy - 11);
  ctx.closePath();
  ctx.fill();

  // Curving horns.
  ctx.strokeStyle = '#746956';
  ctx.lineWidth = 3.4;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(-17, hy - 6);
  ctx.quadraticCurveTo(-41, hy - 15, -45, hy - 37);
  ctx.moveTo(17, hy - 6);
  ctx.quadraticCurveTo(38, hy - 16, 40, hy - 38);
  ctx.stroke();

  // Eyes.
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const eyePulse = (b.phase2 ? 1 : 0.72) + Math.sin(T * 5.2) * 0.2;
  for (const ex of [-8, 8]) {
    const eg = ctx.createRadialGradient(ex, hy + 2, 0, ex, hy + 2, 11);
    eg.addColorStop(0, `rgba(255, 239, 184, ${eyePulse})`);
    eg.addColorStop(0.24, `rgba(255, 117, 43, ${eyePulse * 0.95})`);
    eg.addColorStop(1, 'rgba(194, 42, 12, 0)');
    ctx.fillStyle = eg;
    ctx.beginPath();
    ctx.arc(ex, hy + 2, 11, 0, TAU);
    ctx.fill();
  }
  ctx.fillStyle = '#fff0c3';
  ctx.beginPath();
  ctx.ellipse(-8, hy + 2, 2.2, 1.1, 0, 0, TAU);
  ctx.ellipse(8, hy + 2, 2.2, 1.1, 0, 0, TAU);
  ctx.fill();
  ctx.restore();

  // Crown of cinders.
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  for (let i = 0; i < 5; i++) {
    const fx = -12 + i * 6;
    const fh = 7 + Math.sin(T * 8 + i * 1.9) * 2.5;
    ctx.fillStyle = 'rgba(255, 162, 68, 0.48)';
    ctx.beginPath();
    ctx.ellipse(fx, hy - 31 - fh * 0.2, 1.5, fh, 0, 0, TAU);
    ctx.fill();
  }
  ctx.restore();

  bossFlashOverlay(b);
  ctx.restore();
}

// ---------------------------------------------------------------------------
// Attack telegraphs
// ---------------------------------------------------------------------------

function drawBossTelegraph(b, t) {
  if (!b.windup) return;
  const w = b.windup;
  const progress = 1 - w.t / w.total;
  const color = b.def ? b.def.color : '#ff8b4a';

  ctx.save();
  if (w.kind === 'beam') {
    const y = w.data.y;
    ctx.globalCompositeOperation = 'lighter';
    ctx.setLineDash([13, 11]);
    ctx.lineDashOffset = -t * 80;
    ctx.strokeStyle = `rgba(255, 124, 56, ${0.22 + progress * 0.35})`;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(b.x, y);
    ctx.stroke();
    ctx.setLineDash([]);

    const glow = ctx.createLinearGradient(0, y - 20, 0, y + 20);
    glow.addColorStop(0, 'rgba(255, 76, 32, 0)');
    glow.addColorStop(0.5, `rgba(255, 122, 58, ${0.16 + progress * 0.18})`);
    glow.addColorStop(1, 'rgba(255, 76, 32, 0)');
    ctx.fillStyle = glow;
    ctx.fillRect(0, y - 20, b.x, 40);

    for (let x = 40; x < b.x - 20; x += 70) {
      const offset = (t * 80 + x) % 70;
      ctx.strokeStyle = `rgba(255, 168, 92, ${0.16 + progress * 0.25})`;
      ctx.beginPath();
      ctx.moveTo(x + offset, y - 6);
      ctx.lineTo(x + offset + 8, y);
      ctx.lineTo(x + offset, y + 6);
      ctx.stroke();
    }
  } else if (w.kind === 'rain') {
    for (const x of w.data.xs) {
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      const g = ctx.createLinearGradient(0, 0, 0, H);
      g.addColorStop(0, `rgba(255, 102, 46, ${0.06 + progress * 0.13})`);
      g.addColorStop(0.6, `rgba(255, 91, 38, ${0.02 + progress * 0.06})`);
      g.addColorStop(1, 'rgba(255, 75, 27, 0)');
      ctx.fillStyle = g;
      ctx.fillRect(x - 18, 0, 36, H);
      ctx.strokeStyle = `rgba(255, 164, 91, ${0.14 + progress * 0.3})`;
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(x - 18, 0);
      ctx.lineTo(x - 18, H * (0.4 + progress * 0.5));
      ctx.moveTo(x + 18, 0);
      ctx.lineTo(x + 18, H * (0.4 + progress * 0.5));
      ctx.stroke();
      ctx.restore();
    }
  } else if (w.kind === 'dive' || w.kind === 'dash') {
    const target = w.data;
    ctx.globalCompositeOperation = 'lighter';
    ctx.setLineDash([6, 12]);
    ctx.lineDashOffset = -t * 90;
    ctx.strokeStyle = `rgba(255, 118, 51, ${0.18 + progress * 0.36})`;
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(b.x, b.y);
    ctx.lineTo(target.x, target.y);
    ctx.stroke();
    ctx.setLineDash([]);
    const g = ctx.createRadialGradient(target.x, target.y, 0, target.x, target.y, 58);
    g.addColorStop(0, `rgba(255, 97, 40, ${0.1 + progress * 0.14})`);
    g.addColorStop(1, 'rgba(255, 89, 36, 0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(target.x, target.y, 58, 0, TAU);
    ctx.fill();
  } else {
    // Fan and ring warnings gather at the keeper.
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const radius = 95 + Math.sin(t * 7) * 5;
    ctx.strokeStyle = color.startsWith('#')
      ? color.replace(')', `, ${0.13 + progress * 0.18})`).replace('rgb', 'rgba')
      : `rgba(255, 158, 82, ${0.13 + progress * 0.18})`;
    ctx.strokeStyle = `rgba(255, 162, 89, ${0.12 + progress * 0.2})`;
    ctx.lineWidth = 1.3;
    ctx.beginPath();
    ctx.arc(b.x, b.y, radius, 0, TAU);
    ctx.stroke();
    ctx.restore();
  }
  ctx.restore();
}

'use strict';

// ---------------------------------------------------------------------------
// Run setup, traversal, combat, and boss logic
// ---------------------------------------------------------------------------

function computeMetrics() {
  const min = Math.min(W, H);
  const v = clamp(H / 900, 0.82, 1.08);
  return {
    scale: clamp(min / 760, 0.74, 1.1),
    speed: clamp(W * 0.205, 205, 325),
    gravity: 2550 * v,
    flap: -765 * v,
    playerX: clamp(W * 0.235, 84, 340),
    playerR: 13 * clamp(min / 760, 0.78, 1.1) + 2,
    obstacleW: clamp(W * 0.072, 42, 105),
    spacing: Math.max(290, W * 0.29),
  };
}

function makePlayer() {
  const m = G.metrics;
  return {
    x: m.playerX,
    y: H * 0.46,
    vy: 0,
    r: m.playerR,
    rot: 0,
    wing: 0.4,
    castCd: 0,
    castAnim: 0,
    health: 3,
    maxHealth: 3,
    iframes: 0,
    trailTimer: 0,
    knockX: 0,
  };
}

function resetRun() {
  G.state = 'playing';
  G.prevState = 'playing';
  G.stateTime = 0;
  G.bgScroll = 0;
  G.distance = 0;
  G.souls = 0;
  G.nextBoss = 0;
  G.boss = null;
  G.obstacles = [];
  G.pickups = [];
  G.bolts = [];
  G.projectiles = [];
  G.beams = [];
  G.particles = [];
  G.floaters = [];
  G.spawnTimer = 0;
  G.startHover = 1.35;
  G.shake = 0;
  G.hurtFlash = 0;
  G.healFlash = 0;
  G.flash = 0;
  G.lowHealth = 0;
  G.hintTime = 0;
  G.deathTimer = 0;
  G.bossDefeatTimer = 0;
  G.castHeld = false;
  G.pendingVictory = false;
  G.heartTimer = 0;
  G.metrics = computeMetrics();
  G.player = makePlayer();
  G.speed = G.metrics.speed;
  G.prevGap = H * 0.5;
  G.spawnTimer = G.metrics.spacing / G.speed;

  spawnObstacle(W + 120);
  ui.hint.classList.remove('is-hidden');
  syncFlasks();
  hideBossHud();
  updateRecordDisplay();
}

function baseGapHeight() {
  return clamp(H * 0.315 - Math.min(64, G.distance * 0.075), 170, 305);
}

function spawnObstacle(x) {
  const m = G.metrics;
  const gapH = baseGapHeight();
  const margin = H * 0.12;
  let gapY = G.prevGap + rand(-0.21, 0.21) * H;
  gapY = clamp(gapY, gapH * 0.5 + margin, H - gapH * 0.5 - margin);
  G.prevGap = gapY;
  const w = m.obstacleW * rand(0.88, 1.12);
  const seed = rand(0, 1000);
  G.obstacles.push({ x, w, gapY, gapH, seed, passed: false });

  const soulY = clamp(gapY + rand(-gapH * 0.16, gapH * 0.16), gapY - gapH * 0.22, gapY + gapH * 0.22);
  G.pickups.push({
    x: x + w * 0.48,
    baseY: soulY,
    kind: 'soul',
    phase: rand(0, TAU),
  });

  if (Math.random() < 0.36) {
    G.pickups.push({
      x: x + w * 0.5 + rand(-18, 28),
      baseY: clamp(gapY + rand(-gapH * 0.2, gapH * 0.2), 60, H - 60),
      kind: 'soul',
      phase: rand(0, TAU),
    });
  }

  if (G.player && G.player.health < G.player.maxHealth && G.obstacles.length % 4 === 2) {
    G.pickups.push({
      x: x + w * 0.52,
      baseY: gapY,
      kind: 'estus',
      phase: rand(0, TAU),
    });
  }
}

function updateGame(dt) {
  G.time += dt;
  G.stateTime += dt;

  G.shake = Math.max(0, G.shake - dt * 32);
  G.hurtFlash = Math.max(0, G.hurtFlash - dt * 2.2);
  G.healFlash = Math.max(0, G.healFlash - dt * 2);
  G.flash = Math.max(0, G.flash - dt * 3.4);

  if (G.state === 'title' || G.state === 'paused' || G.state === 'gameover' || G.state === 'victory') {
    return;
  }

  if (G.state === 'dying') {
    updateDying(dt);
    updateParticles(dt);
    updateFloaters(dt);
    return;
  }

  if (G.state === 'bossDefeat') {
    updateBossDefeat(dt);
    updateParticles(dt);
    updateFloaters(dt);
    return;
  }

  if (G.state === 'playing') {
    updateTraversal(dt);
  } else if (G.state === 'boss') {
    updateBossFight(dt);
  }

  updateParticles(dt);
  updateFloaters(dt);

  if (G.player) {
    G.lowHealth = G.player.health === 1 ? 1 : 0;
  }
}

function updateTraversal(dt) {
  const p = G.player;
  G.speed = G.metrics.speed + Math.min(105, G.distance * 0.16);
  G.distance += dt * (8.5 + G.speed * 0.025);
  G.bgScroll += G.speed * dt;
  G.hintTime += dt;
  if (G.hintTime > 7.5) ui.hint.classList.add('is-hidden');

  updatePlayerMotion(dt);

  G.spawnTimer -= dt;
  if (G.spawnTimer <= 0) {
    spawnObstacle(W + 120);
    G.spawnTimer = G.metrics.spacing / Math.max(180, G.speed);
  }

  for (let i = G.obstacles.length - 1; i >= 0; i--) {
    const o = G.obstacles[i];
    o.x -= G.speed * dt;
    if (!o.passed && o.x + o.w < p.x) {
      o.passed = true;
      G.souls += 4;
      spawnSpark(p.x - p.r, p.y, 3, 'rgba(127, 226, 239, ALPHA)', 1.6);
    }
    if (o.x < -220) G.obstacles.splice(i, 1);
  }

  for (let i = G.pickups.length - 1; i >= 0; i--) {
    const item = G.pickups[i];
    item.x -= G.speed * dt;
    if (item.x < -80) {
      G.pickups.splice(i, 1);
      continue;
    }
    const iy = item.baseY + Math.sin(G.time * 2.1 + item.phase) * 6;
    const rr = item.kind === 'estus' ? 26 : 21;
    if (dist(p.x, p.y, item.x, iy) < p.r + rr) {
      if (item.kind === 'estus') {
        if (p.health < p.maxHealth) {
          healPlayer('estus');
        } else {
          addSouls(24, item.x, iy);
          burst(item.x, iy, 9, ['rgba(255, 199, 105, ALPHA)', 'rgba(255, 136, 47, ALPHA)'], 120);
        }
        sound.heal();
      } else {
        addSouls(9, item.x, iy);
        sound.collect();
        burst(item.x, iy, 8, ['rgba(157, 245, 255, ALPHA)', 'rgba(82, 194, 231, ALPHA)'], 90);
      }
      G.pickups.splice(i, 1);
    }
  }

  checkObstacleCollisions();
  checkBossTrigger();
}

function updatePlayerMotion(dt) {
  const p = G.player;
  p.castCd = Math.max(0, p.castCd - dt);
  p.castAnim = Math.max(0, p.castAnim - dt * 5);
  p.iframes = Math.max(0, p.iframes - dt);
  p.wing = Math.max(0, p.wing - dt * 2.2);

  if (G.castHeld && p.castCd <= 0) castSoulBolt();

  if (G.startHover > 0 && G.state === 'playing') {
    G.startHover -= dt;
    const targetY = H * 0.455 + Math.sin(G.time * 2.2) * 7;
    p.y = lerp(p.y, targetY, 1 - Math.exp(-dt * 8));
    p.vy = 0;
    p.rot = lerp(p.rot, 0, 1 - Math.exp(-dt * 8));
    emitPlayerTrail(dt);
    if (G.startHover <= 0) p.wing = 1;
    return;
  }

  p.vy += G.metrics.gravity * dt;
  p.y += p.vy * dt;
  p.knockX = lerp(p.knockX, 0, 1 - Math.exp(-dt * 6));
  p.x = G.metrics.playerX + p.knockX;
  const rotTarget = clamp(p.vy / 1800, -0.4, 0.55);
  p.rot = lerp(p.rot, rotTarget, 1 - Math.exp(-dt * 9));

  const ceiling = 8;
  const floor = H - 8;
  if (p.y - p.r < ceiling) {
    p.y = ceiling + p.r;
    if (p.vy < 0) p.vy = 0;
    if (G.state === 'playing' || G.state === 'boss') damagePlayer('ceiling');
  }
  if (p.y + p.r > floor) {
    p.y = floor - p.r;
    p.vy = -G.metrics.flap * 0.48;
    if (G.state === 'playing' || G.state === 'boss') damagePlayer('floor');
  }

  emitPlayerTrail(dt);
}

function emitPlayerTrail(dt) {
  const p = G.player;
  p.trailTimer -= dt;
  if (p.trailTimer > 0) return;
  p.trailTimer = 0.045;
  const color = Math.random() < 0.7
    ? 'rgba(236, 127, 54, ALPHA)'
    : 'rgba(112, 210, 226, ALPHA)';
  G.particles.push({
    x: p.x - 12 + rand(-5, 5),
    y: p.y + rand(-5, 8),
    vx: -rand(15, 55) - (G.state === 'playing' ? G.speed * 0.05 : 0),
    vy: rand(-15, 16),
    life: rand(0.38, 0.8),
    maxLife: 0.8,
    size: rand(1.1, 2.6),
    color,
    glow: true,
    alpha: rand(0.25, 0.65),
    gravity: -10,
    drag: 1.5,
  });
}

function flap() {
  if (G.state !== 'playing' && G.state !== 'boss') return;
  const p = G.player;
  if (!p) return;
  if (G.startHover > 0) G.startHover = 0;
  p.vy = G.metrics.flap;
  p.wing = 1;
  p.trailTimer = 0;
  sound.flap();
  for (let i = 0; i < 4; i++) {
    G.particles.push({
      x: p.x - 12 + rand(-6, 8),
      y: p.y + rand(2, 12),
      vx: rand(-80, 8),
      vy: rand(20, 80),
      life: rand(0.24, 0.55),
      maxLife: 0.55,
      size: rand(1.4, 3.2),
      color: i % 2 ? 'rgba(248, 159, 71, ALPHA)' : 'rgba(139, 222, 235, ALPHA)',
      glow: true,
      alpha: 0.65,
      gravity: 10,
      drag: 2.2,
    });
  }
}

function checkObstacleCollisions() {
  const p = G.player;
  if (p.iframes > 0 || G.state !== 'playing') return;
  for (const o of G.obstacles) {
    const topEdge = o.gapY - o.gapH * 0.5;
    const bottomEdge = o.gapY + o.gapH * 0.5;
    const rx = o.x + 9;
    const rw = o.w - 18;
    if (circleRect(p.x, p.y, p.r, rx, -40, rw, topEdge + 46) ||
        circleRect(p.x, p.y, p.r, rx, bottomEdge - 6, rw, H - bottomEdge + 46)) {
      damagePlayer('spikes');
      p.knockX = -26;
      p.vy = p.y < o.gapY ? -G.metrics.flap * 0.45 : G.metrics.flap * 0.34;
      return;
    }
  }
}

function checkBossTrigger() {
  if (G.nextBoss >= BOSS_DEFS.length) return;
  const def = BOSS_DEFS[G.nextBoss];
  if (G.distance >= def.threshold) startBoss(def);
}

function startBoss(def) {
  G.state = 'boss';
  G.stateTime = 0;
  G.speed = 0;
  G.obstacles = [];
  G.pickups = [];
  G.bolts = [];
  G.projectiles = [];
  G.beams = [];
  G.hintTime = 99;
  ui.hint.classList.add('is-hidden');

  const sc = clamp(Math.min(W, H) / 720, 0.72, 1.12);
  const targetX = W * (W < 760 ? 0.705 : 0.735);
  const baseY = H * (def.id === 'choir' ? 0.43 : 0.405);
  G.boss = {
    def,
    type: def.id,
    x: W + 190,
    y: baseY - H * 0.06,
    targetX,
    baseY,
    bob: H * (def.id === 'choir' ? 0.028 : 0.038),
    scale: sc,
    hp: def.hp,
    maxHp: def.hp,
    enterT: 0,
    t: 0,
    attackCd: 1.6,
    windup: null,
    dive: null,
    patternIndex: 0,
    phase2: false,
    flash: 0,
    dead: false,
    deathT: 0,
    hitR: 59 * sc,
  };

  const p = G.player;
  p.iframes = Math.max(p.iframes, 1.2);
  p.vy = Math.min(p.vy, -120);
  G.heartTimer = 0.8;
  G.shake = 18;

  setState('boss');
  showBossHud(def);
  updateBossFill();
  showBanner(def.kicker, def.name, '', 2300);
  sound.roar();
  G.flash = 0.16;
  G.flashColor = '#f0b46b';
  spawnBurst(W * 0.7, H * 0.4, 22, ['rgba(230, 154, 75, ALPHA)', 'rgba(132, 67, 36, ALPHA)'], 240);
}

function updateBossFight(dt) {
  const b = G.boss;
  if (!b) return;
  const p = G.player;

  updatePlayerMotion(dt);
  b.t += dt;
  b.flash = Math.max(0, b.flash - dt * 4.5);

  if (b.dead) {
    b.deathT += dt;
    return;
  }

  if (b.enterT < 1) {
    b.enterT = Math.min(1, b.enterT + dt / 1.45);
    const k = easeOutCubic(b.enterT);
    b.x = lerp(W + 190, b.targetX, k);
    b.y = b.baseY - H * 0.06 * (1 - k) + Math.sin(b.t * 1.2) * b.bob * 0.4;
    if (b.enterT >= 0.72) b.attackCd = Math.min(b.attackCd, 0.9);
  } else if (b.dive) {
    updateBossDive(dt);
  } else {
    b.x = lerp(b.x, b.targetX, 1 - Math.exp(-dt * 4));
    const targetY = b.baseY + Math.sin(b.t * 1.15) * b.bob;
    b.y = lerp(b.y, targetY, 1 - Math.exp(-dt * 2.3));

    if (b.windup) {
      b.windup.t -= dt;
      if (b.windup.t <= 0) {
        const done = b.windup;
        b.windup = null;
        executeBossAttack(done);
      }
    } else {
      b.attackCd -= dt;
      if (b.attackCd <= 0) chooseBossAttack();
    }
  }

  if (b.enterT >= 1 && !b.dead) {
    const contactR = b.hitR * (b.dive ? 0.92 : 0.76);
    if (dist(p.x, p.y, b.x, b.y) < contactR + p.r) {
      damagePlayer('boss');
      p.vy = -G.metrics.flap * 0.65;
      p.knockX = -20;
    }
  }

  G.heartTimer -= dt;
  if (G.heartTimer <= 0) {
    sound.thump(b.phase2);
    G.heartTimer = b.phase2 ? 0.66 : 1;
  }

  updateBolts(dt);
  updateProjectiles(dt);
  updateBeams(dt);
}

function chooseBossAttack() {
  const b = G.boss;
  const p = G.player;
  const def = b.def;
  const kind = def.patterns[b.patternIndex % def.patterns.length];
  b.patternIndex++;
  const speedUp = b.phase2 ? 0.84 : 1;
  let warn = 0.55;
  const data = {};

  if (kind === 'beam') {
    warn = 0.92;
    data.y = clamp(p.y, H * 0.17, H * 0.83);
  } else if (kind === 'rain') {
    warn = 0.88;
    const total = b.phase2 ? 6 : 4;
    const base = p.x;
    const spread = Math.min(W * 0.44, 460);
    data.xs = [];
    for (let i = 0; i < total; i++) {
      const t = total === 1 ? 0.5 : i / (total - 1);
      data.xs.push(clamp(base + (t - 0.5) * spread + rand(-W * 0.04, W * 0.04), 35, W - 35));
    }
  } else if (kind === 'dive' || kind === 'dash') {
    warn = 0.6;
    data.x = clamp(W * (kind === 'dash' ? 0.48 : 0.4), W * 0.3, W * 0.55);
    data.y = p.y;
  } else if (kind === 'radial') {
    warn = 0.66;
  } else {
    warn = 0.46;
  }

  b.windup = {
    kind,
    t: warn * speedUp,
    total: warn * speedUp,
    data,
  };
  sound.tone(kind === 'beam' ? 118 : 86, 0.3, 'sine', 0.035, kind === 'beam' ? 72 : 56);
}

function executeBossAttack(w) {
  const b = G.boss;
  if (!b || b.dead) return;
  const p = G.player;
  const def = b.def;
  const color = def.id === 'choir' ? 'rgba(132, 237, 251, 0.9)' : def.id === 'cinder' ? 'rgba(255, 119, 49, 0.95)' : 'rgba(255, 178, 81, 0.95)';
  const core = def.id === 'choir' ? 'rgba(236, 255, 255, 0.98)' : 'rgba(255, 246, 210, 0.98)';

  if (w.kind === 'fan') {
    const count = b.phase2 ? 5 : 3;
    const baseAngle = Math.atan2(p.y - b.y, p.x - b.x);
    const speed = clamp(W * 0.22, 175, 325);
    for (let i = 0; i < count; i++) {
      const a = baseAngle + (i - (count - 1) / 2) * 0.17;
      spawnProjectile(b.x - 22, b.y + 5, Math.cos(a) * speed, Math.sin(a) * speed, {
        color, core, r: clamp(8 * b.scale, 6.4, 9.5),
      });
    }
    sound.tone(260, 0.2, 'sawtooth', 0.04, 520);
    sound.noiseBurst(0.18, 800, 0.025, 'bandpass');
  } else if (w.kind === 'radial') {
    const count = b.phase2 ? 14 : 10;
    const speed = clamp(W * 0.16, 120, 235);
    const offset = Math.random() * TAU;
    for (let i = 0; i < count; i++) {
      const a = offset + (i / count) * TAU;
      spawnProjectile(b.x, b.y, Math.cos(a) * speed, Math.sin(a) * speed, {
        color, core, r: clamp(8.5 * b.scale, 6.6, 10),
      });
    }
    sound.tone(330, 0.4, 'triangle', 0.045, 130);
    G.shake = Math.max(G.shake, 8);
  } else if (w.kind === 'rain') {
    const speed = H * (b.phase2 ? 0.52 : 0.43);
    for (const x of w.data.xs) {
      spawnProjectile(x, -24, rand(-12, 12), speed, {
        color,
        core,
        r: clamp(9 * b.scale, 7, 11),
        kind: 'ember',
      });
    }
    sound.tone(150, 0.5, 'sawtooth', 0.05, 70);
  } else if (w.kind === 'beam') {
    const width = clamp(H * 0.032, 18, 34);
    G.beams.push({ y: w.data.y, t: 0, life: 0.42, x2: b.x, width, hit: false });
    sound.tone(90, 0.65, 'sawtooth', 0.11, 35);
    sound.noiseBurst(0.5, 500, 0.06, 'bandpass');
    G.shake = 16;
    G.flash = 0.12;
    G.flashColor = def.color;
  } else if (w.kind === 'dive' || w.kind === 'dash') {
    b.dive = {
      t: 0,
      dur: w.kind === 'dash' ? 1.02 : 1.28,
      fromX: b.x,
      fromY: b.y,
      targetX: w.data.x,
      targetY: w.data.y,
    };
    sound.tone(80, 0.85, 'sawtooth', 0.1, 38);
    G.shake = Math.max(G.shake, 10);
  }

  b.attackCd = (b.phase2 ? def.cooldown2 : def.cooldown) * (b.phase2 ? 0.9 : 1);
}

function updateBossDive(dt) {
  const b = G.boss;
  const d = b.dive;
  d.t += dt;
  const u = clamp(d.t / d.dur, 0, 1);
  const k = u < 0.44
    ? easeInOutCubic(u / 0.44)
    : 1 - easeInOutCubic((u - 0.44) / 0.56);
  b.x = lerp(d.fromX, d.targetX, k);
  b.y = lerp(d.fromY, d.targetY, k);
  if (u >= 1) {
    b.dive = null;
    b.x = b.targetX;
    b.y = b.baseY;
    b.attackCd = Math.min(b.attackCd, 0.9);
  }
}

function spawnProjectile(x, y, vx, vy, opts = {}) {
  G.projectiles.push({
    x,
    y,
    vx,
    vy,
    r: opts.r || 8,
    kind: opts.kind || 'orb',
    color: opts.color || 'rgba(255, 148, 74, 0.9)',
    core: opts.core || 'rgba(255, 247, 218, 0.98)',
    life: opts.life || 6,
    rot: rand(0, TAU),
    phase: rand(0, TAU),
  });
}

function updateProjectiles(dt) {
  const p = G.player;
  for (let i = G.projectiles.length - 1; i >= 0; i--) {
    const pr = G.projectiles[i];
    pr.x += pr.vx * dt;
    pr.y += pr.vy * dt;
    pr.rot += dt * 3;
    pr.life -= dt;
    if (pr.life <= 0 || pr.x < -120 || pr.x > W + 160 || pr.y < -140 || pr.y > H + 140) {
      G.projectiles.splice(i, 1);
      continue;
    }
    if (p.iframes <= 0 && dist(p.x, p.y, pr.x, pr.y) < p.r + pr.r * 0.82) {
      G.projectiles.splice(i, 1);
      damagePlayer('projectile');
      p.vy = -G.metrics.flap * 0.5;
      for (let j = 0; j < 12; j++) {
        spawnSpark(pr.x, pr.y, 1, 'rgba(255, 128, 52, ALPHA)', 2.5);
      }
    }
  }
}

function updateBeams(dt) {
  const p = G.player;
  for (let i = G.beams.length - 1; i >= 0; i--) {
    const b = G.beams[i];
    b.t += dt;
    if (!b.hit && b.t < b.life * 0.72 && p.iframes <= 0) {
      if (Math.abs(p.y - b.y) < b.width * 1.1 + p.r) {
        b.hit = true;
        damagePlayer('beam');
        p.vy = -G.metrics.flap * 0.7;
      }
    }
    if (b.t >= b.life) G.beams.splice(i, 1);
  }
}

function castSoulBolt() {
  const p = G.player;
  if (!p || (G.state !== 'playing' && G.state !== 'boss')) return;
  if (p.castCd > 0) return;
  p.castCd = 0.34;
  p.castAnim = 1;
  const b = G.boss;
  let angle = 0;
  if (b && !b.dead) {
    angle = Math.atan2(b.y - p.y, b.x - p.x);
  }
  const speed = clamp(W * 0.68, 720, 990);
  G.bolts.push({
    x: p.x + 26,
    y: p.y - 2,
    vx: Math.cos(angle) * speed,
    vy: Math.sin(angle) * speed,
    life: 1.85,
    dmg: 16,
    speed,
  });
  sound.cast();
  p.vy += 16;
  for (let i = 0; i < 5; i++) {
    spawnSpark(p.x + 30, p.y - 2, 1, 'rgba(139, 237, 255, ALPHA)', 2);
  }
}

function updateBolts(dt) {
  const b = G.boss;
  for (let i = G.bolts.length - 1; i >= 0; i--) {
    const bolt = G.bolts[i];
    bolt.life -= dt;
    if (bolt.life <= 0) {
      G.bolts.splice(i, 1);
      continue;
    }

    if (b && !b.dead) {
      const dx = b.x - bolt.x;
      const dy = b.y - bolt.y;
      const d = Math.hypot(dx, dy) || 1;
      bolt.vx += (dx / d) * 1250 * dt;
      bolt.vy += (dy / d) * 1250 * dt;
      const sp = Math.hypot(bolt.vx, bolt.vy) || 1;
      const target = Math.max(bolt.speed * 1.04, 760);
      bolt.vx = bolt.vx / sp * target;
      bolt.vy = bolt.vy / sp * target;
    }

    bolt.x += bolt.vx * dt;
    bolt.y += bolt.vy * dt;

    // Soul bolts can intercept incoming missiles.
    let intercepted = false;
    for (let j = G.projectiles.length - 1; j >= 0; j--) {
      const pr = G.projectiles[j];
      if (dist(bolt.x, bolt.y, pr.x, pr.y) < pr.r + 9) {
        G.projectiles.splice(j, 1);
        G.bolts.splice(i, 1);
        interceptKill(bolt.x, bolt.y);
        intercepted = true;
        break;
      }
    }
    if (intercepted) continue;

    if (b && !b.dead && b.enterT >= 0.92 && dist(bolt.x, bolt.y, b.x, b.y) < b.hitR + 7) {
      G.bolts.splice(i, 1);
      damageBoss(bolt.dmg);
      continue;
    }

    if (bolt.x < -80 || bolt.x > W + 120 || bolt.y < -100 || bolt.y > H + 100) {
      G.bolts.splice(i, 1);
    }
  }
}

function interceptKill(x, y) {
  sound.tone(760, 0.18, 'triangle', 0.035, 1240);
  for (let i = 0; i < 10; i++) {
    spawnSpark(x, y, 1, 'rgba(186, 249, 255, ALPHA)', 2.4);
  }
}

function damageBoss(dmg) {
  const b = G.boss;
  if (!b || b.dead || b.enterT < 0.7) return;
  b.hp = Math.max(0, b.hp - dmg);
  b.flash = 1;
  G.shake = Math.max(G.shake, 7);
  sound.hitBoss();
  updateBossFill();
  for (let i = 0; i < 9; i++) {
    spawnSpark(b.x + rand(-b.hitR * 0.3, b.hitR * 0.3), b.y + rand(-b.hitR * 0.3, b.hitR * 0.3), 1, 'rgba(163, 244, 255, ALPHA)', 3);
  }

  if (!b.phase2 && b.hp <= b.maxHp * 0.5) {
    b.phase2 = true;
    b.windup = null;
    b.attackCd = 0.75;
    sound.roar();
    G.flash = 0.2;
    G.flashColor = b.def.id === 'choir' ? '#b3f1ff' : '#ffb06c';
    G.shake = 18;
    showBanner('The keeper remembers fury', b.def.name, 'is-blood', 1600);
    spawnBurst(b.x, b.y, 25, ['rgba(255, 180, 86, ALPHA)', 'rgba(255, 96, 41, ALPHA)'], 260);
  }

  if (b.hp <= 0) killBoss();
}

function killBoss() {
  const b = G.boss;
  if (!b || b.dead) return;
  b.dead = true;
  b.deathT = 0;
  b.windup = null;
  b.dive = null;
  b.flash = 0;
  G.projectiles = [];
  G.beams = [];
  G.bolts = [];
  G.state = 'bossDefeat';
  G.stateTime = 0;
  G.bossDefeatTimer = 0;
  G.souls += b.def.reward;
  G.shake = 22;
  G.flash = 0.32;
  G.flashColor = '#ffe1aa';
  sound.roar();
  sound.victory();
  spawnBurst(b.x, b.y, 44, ['rgba(255, 205, 115, ALPHA)', 'rgba(255, 117, 48, ALPHA)', 'rgba(135, 234, 245, ALPHA)'], 320);
  if (G.player.health < G.player.maxHealth) healPlayer('grace');
  setState('bossDefeat');
  showBanner('Great enemy felled', b.def.name, 'is-gold', 2600);
  G.pendingVictory = G.nextBoss >= BOSS_DEFS.length - 1;
  updateBossFill();
  saveBest();
}

function updateBossDefeat(dt) {
  const b = G.boss;
  const p = G.player;
  if (!b) return;
  b.t += dt;
  b.deathT += dt;
  G.bossDefeatTimer += dt;

  p.y += Math.sin(G.time * 1.6) * 12 * dt;
  p.wing = Math.max(p.wing, 0.3);
  p.rot = lerp(p.rot, -0.1, dt * 2);
  p.iframes = 1;

  // The keeper unthreads into embers.
  if (b.deathT < 2.4) {
    for (let i = 0; i < 2; i++) {
      G.particles.push({
        x: b.x + rand(-b.hitR * 0.8, b.hitR * 0.8),
        y: b.y + rand(-b.hitR * 0.7, b.hitR * 0.7),
        vx: rand(-35, 40),
        vy: rand(-95, -20),
        life: rand(0.5, 1.4),
        maxLife: 1.4,
        size: rand(1.2, 3.2),
        color: i % 2 ? 'rgba(255, 195, 106, ALPHA)' : 'rgba(134, 228, 240, ALPHA)',
        glow: true,
        alpha: 0.7,
        gravity: -12,
        drag: 0.7,
      });
    }
  }

  if (G.bossDefeatTimer > 3.15) finishBoss();
}

function finishBoss() {
  const wasFinal = G.nextBoss >= BOSS_DEFS.length - 1;
  G.nextBoss++;
  G.boss = null;
  G.projectiles = [];
  G.beams = [];
  G.bolts = [];
  hideBossHud();

  if (wasFinal) {
    triggerVictory();
    return;
  }

  G.state = 'playing';
  G.stateTime = 0;
  G.speed = G.metrics.speed;
  G.spawnTimer = 1.1;
  G.prevGap = H * 0.5;
  G.obstacles = [];
  G.pickups = [];
  G.player.iframes = 1.2;
  G.hintTime = 99;
  spawnObstacle(W + 130);
  setState('playing');
  showBanner('The way opens', 'Descend deeper', '', 1900);
}

function addSouls(n, x, y, silent = true) {
  G.souls += n;
  if (x !== undefined) {
    G.floaters.push({
      text: `+${n}`,
      x,
      y: y - 18,
      vy: -36,
      life: 0.9,
      maxLife: 0.9,
      size: clamp(Math.min(W, H) * 0.019, 12, 17),
      color: '#a9f5ff',
      shadow: '#4bbad5',
    });
  }
  if (!silent) sound.collect();
}

function healPlayer(source) {
  const p = G.player;
  if (!p) return;
  if (p.health >= p.maxHealth) {
    addSouls(18, p.x, p.y);
    return;
  }
  p.health = Math.min(p.maxHealth, p.health + 1);
  G.healFlash = 1;
  G.lowHealth = p.health === 1 ? 1 : 0;
  syncFlasks('heal');
  sound.heal();
  for (let i = 0; i < 18; i++) {
    G.particles.push({
      x: p.x + rand(-22, 22),
      y: p.y + rand(-22, 22),
      vx: rand(-25, 25),
      vy: rand(-70, -10),
      life: rand(0.4, 1.1),
      maxLife: 1.1,
      size: rand(1.1, 2.8),
      color: 'rgba(255, 207, 110, ALPHA)',
      glow: true,
      alpha: 0.8,
      gravity: -20,
      drag: 1,
    });
  }
}

function damagePlayer(source) {
  const p = G.player;
  if (!p || p.iframes > 0 || (G.state !== 'playing' && G.state !== 'boss')) return;
  if (source === 'floor' && G.startHover > 0.7) return;
  p.health = Math.max(0, p.health - 1);
  p.iframes = 1.4;
  G.hurtFlash = 1;
  G.shake = Math.max(G.shake, 14);
  G.lowHealth = p.health === 1 ? 1 : 0;
  syncFlasks('hurt');
  sound.hurt();
  spawnBurst(p.x, p.y, 16, ['rgba(235, 84, 50, ALPHA)', 'rgba(148, 34, 22, ALPHA)'], 190);

  if (p.health <= 0) die();
}

function die() {
  if (G.state === 'dying' || G.state === 'gameover') return;
  const p = G.player;
  p.health = 0;
  G.state = 'dying';
  G.stateTime = 0;
  G.deathTimer = 0;
  G.speed = 0;
  G.projectiles = [];
  G.beams = [];
  G.shake = 20;
  G.flash = 0.12;
  G.flashColor = '#9e1e1b';
  sound.death();
  spawnBurst(p.x, p.y, 34, ['rgba(224, 82, 47, ALPHA)', 'rgba(106, 24, 18, ALPHA)', 'rgba(134, 220, 229, ALPHA)'], 260);
  setState('dying');
  saveBest();
}

function updateDying(dt) {
  const p = G.player;
  G.deathTimer += dt;
  if (p) {
    p.vy += G.metrics.gravity * 0.55 * dt;
    p.y += p.vy * dt;
    p.rot += dt * 1.8;
    if (p.y > H + 80) p.y = H + 80;
  }
  G.shake = Math.max(0, G.shake - dt * 20);
}

function updateParticles(dt) {
  for (let i = G.particles.length - 1; i >= 0; i--) {
    const p = G.particles[i];
    p.life -= dt;
    if (p.life <= 0) {
      G.particles.splice(i, 1);
      continue;
    }
    const damp = Math.exp(-p.drag * dt);
    p.vx *= damp;
    p.vy = p.vy * damp + p.gravity * dt;
    p.x += p.vx * dt;
    p.y += p.vy * dt;
  }
  if (G.particles.length > 420) G.particles.splice(0, G.particles.length - 420);
}

function updateFloaters(dt) {
  for (let i = G.floaters.length - 1; i >= 0; i--) {
    const f = G.floaters[i];
    f.life -= dt;
    f.y += f.vy * dt;
    if (f.life <= 0) G.floaters.splice(i, 1);
  }
}

function spawnBurst(x, y, count, colors, speed = 180) {
  for (let i = 0; i < count; i++) {
    const a = rand(0, TAU);
    const s = rand(speed * 0.2, speed);
    G.particles.push({
      x: x + rand(-6, 6),
      y: y + rand(-6, 6),
      vx: Math.cos(a) * s,
      vy: Math.sin(a) * s - 20,
      life: rand(0.35, 1.15),
      maxLife: 1.15,
      size: rand(1.4, 4),
      color: colors[randInt(0, colors.length - 1)],
      glow: true,
      alpha: rand(0.35, 0.9),
      gravity: rand(-35, 30),
      drag: rand(0.6, 1.8),
    });
  }
}

function spawnSpark(x, y, count, color, speed) {
  for (let i = 0; i < count; i++) {
    const a = rand(0, TAU);
    const s = rand(8, speed * 26);
    G.particles.push({
      x,
      y,
      vx: Math.cos(a) * s,
      vy: Math.sin(a) * s,
      life: rand(0.2, 0.55),
      maxLife: 0.55,
      size: rand(1, 2.4),
      color,
      glow: true,
      alpha: 0.8,
      gravity: 12,
      drag: 2,
    });
  }
}

function currentScore() {
  return G.souls + Math.floor(G.distance);
}

function saveBest() {
  const score = currentScore();
  if (score > G.best) {
    G.best = score;
    safeSet('hollowwing-best', String(G.best));
  }
  updateRecordDisplay();
}

'use strict';

// ---------------------------------------------------------------------------
// Screen state, UI, rendering orchestration, input, and main loop
// ---------------------------------------------------------------------------

let W = Math.max(320, window.innerWidth);
let H = Math.max(400, window.innerHeight);
let DPR = Math.min(window.devicePixelRatio || 1, 2);
let bannerTimeout = 0;
let lastFrame = performance.now();

function setState(next) {
  G.state = next;
  G.stateTime = 0;
  document.body.dataset.state = next;
}

function showScreen(screen) {
  screen.classList.add('is-visible');
}

function hideAllScreens() {
  ui.titleScreen.classList.remove('is-visible');
  ui.pauseScreen.classList.remove('is-visible');
  ui.deathScreen.classList.remove('is-visible');
  ui.victoryScreen.classList.remove('is-visible');
}

function updateRecordDisplay() {
  ui.bestScore.textContent = G.best.toLocaleString('en-US');
}

function syncFlasks(effect = '') {
  const p = G.player;
  const health = p ? p.health : 3;
  ui.flasks.forEach((el, i) => {
    const wasFull = el.classList.contains('is-full');
    const isFull = i < health;
    el.classList.toggle('is-full', isFull);
    el.classList.remove('just-filled', 'just-lost');
    if (effect === 'hurt' && wasFull && !isFull) {
      el.classList.add('just-lost');
      window.setTimeout(() => el.classList.remove('just-lost'), 550);
    }
    if (effect === 'heal' && !wasFull && isFull) {
      el.classList.add('just-filled');
      window.setTimeout(() => el.classList.remove('just-filled'), 800);
    }
  });
}

function showBossHud(def) {
  ui.bossKicker.textContent = def.kicker;
  ui.bossName.textContent = def.name;
  ui.bossFill.style.width = '100%';
  ui.bossHud.classList.add('is-active');
}

function hideBossHud() {
  ui.bossHud.classList.remove('is-active');
  ui.bossFill.style.width = '0%';
}

function updateBossFill() {
  if (!G.boss) {
    ui.bossFill.style.width = '0%';
    return;
  }
  ui.bossFill.style.width = `${clamp(G.boss.hp / G.boss.maxHp, 0, 1) * 100}%`;
}

function showBanner(kicker, title, modifier = '', duration = 2200) {
  window.clearTimeout(bannerTimeout);
  ui.bannerKicker.textContent = kicker;
  ui.bannerTitle.textContent = title;
  ui.banner.className = 'banner';
  if (modifier) {
    const type = modifier.startsWith('is-') ? modifier : `is-${modifier}`;
    ui.banner.classList.add(type);
  }
  void ui.banner.offsetWidth;
  ui.banner.classList.add('is-visible');
  bannerTimeout = window.setTimeout(() => {
    ui.banner.classList.remove('is-visible');
  }, duration);
}

function clearBanner() {
  window.clearTimeout(bannerTimeout);
  ui.banner.classList.remove('is-visible');
}

function beginRun() {
  sound.init();
  sound.ui();
  if (document.activeElement && document.activeElement.blur) document.activeElement.blur();
  hideAllScreens();
  clearBanner();
  hideBossHud();
  resetRun();
  setState('playing');
  updateRecordDisplay();
}

function togglePause() {
  if (G.state === 'playing' || G.state === 'boss' || G.state === 'bossDefeat') {
    G.prevState = G.state;
    G.castHeld = false;
    setState('paused');
    showScreen(ui.pauseScreen);
    sound.ui();
  } else if (G.state === 'paused') {
    setState(G.prevState || 'playing');
    ui.pauseScreen.classList.remove('is-visible');
    lastFrame = performance.now();
    sound.ui();
  }
}

function resumeRun() {
  if (G.state !== 'paused') return;
  setState(G.prevState || 'playing');
  ui.pauseScreen.classList.remove('is-visible');
  lastFrame = performance.now();
  sound.ui();
}

function showDeathScreen() {
  if (G.state !== 'dying') return;
  saveBest();
  setState('gameover');
  hideBossHud();
  clearBanner();
  ui.hint.classList.add('is-hidden');
  ui.deathSouls.textContent = G.souls.toLocaleString('en-US');
  ui.deathDepth.textContent = `${Math.floor(G.distance)} m`;
  ui.deathBosses.textContent = String(G.nextBoss);
  ui.deathLine.textContent = DEATH_LINES[randInt(0, DEATH_LINES.length - 1)];
  showScreen(ui.deathScreen);
}

function triggerVictory() {
  saveBest();
  setState('victory');
  hideBossHud();
  clearBanner();
  ui.hint.classList.add('is-hidden');
  G.projectiles = [];
  G.beams = [];
  G.bolts = [];
  ui.victorySouls.textContent = G.souls.toLocaleString('en-US');
  ui.victoryDepth.textContent = `${Math.floor(G.distance)} m`;
  ui.victoryBest.textContent = G.best.toLocaleString('en-US');
  showScreen(ui.victoryScreen);
  sound.init();
  sound.victory();
  G.flash = 0.35;
  G.flashColor = '#ffd997';
  G.shake = 14;
}

function returnToTitle() {
  hideAllScreens();
  hideBossHud();
  clearBanner();
  G.boss = null;
  G.obstacles = [];
  G.pickups = [];
  G.bolts = [];
  G.projectiles = [];
  G.beams = [];
  G.particles = [];
  G.floaters = [];
  G.player = makePlayer();
  G.player.y = H * 0.5;
  G.castHeld = false;
  G.shake = 0;
  G.hurtFlash = 0;
  G.healFlash = 0;
  G.flash = 0;
  G.lowHealth = 0;
  setState('title');
  updateRecordDisplay();
  ui.titleScreen.classList.remove('is-visible');
  void ui.titleScreen.offsetWidth;
  ui.titleScreen.classList.add('is-visible');
  sound.ui();
}

function toggleMute() {
  sound.init();
  sound.setMuted(!G.muted);
  document.body.classList.toggle('is-muted', G.muted);
  ui.muteBtn.setAttribute('aria-label', G.muted ? 'Unmute sound' : 'Mute sound');
  ui.muteBtn.setAttribute('title', G.muted ? 'Unmute sound' : 'Mute sound');
}

function resize() {
  W = Math.max(320, window.innerWidth);
  H = Math.max(400, window.innerHeight);
  DPR = Math.min(window.devicePixelRatio || 1, 2);
  canvas.width = Math.round(W * DPR);
  canvas.height = Math.round(H * DPR);
  canvas.style.width = `${W}px`;
  canvas.style.height = `${H}px`;
  ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
  G.metrics = computeMetrics();

  if (G.player) {
    G.player.x = G.metrics.playerX;
    G.player.r = G.metrics.playerR;
    G.player.y = clamp(G.player.y, G.metrics.playerR + 10, H - G.metrics.playerR - 10);
  }
  if (G.boss) {
    const sc = clamp(Math.min(W, H) / 720, 0.72, 1.12);
    G.boss.scale = sc;
    G.boss.targetX = W * (W < 760 ? 0.705 : 0.735);
    G.boss.baseY = H * (G.boss.def.id === 'choir' ? 0.43 : 0.405);
    G.boss.hitR = 59 * sc;
  }
  makeMotes();
}

function drawScene() {
  const shake = G.shake;
  const sx = shake > 0.1 ? rand(-shake, shake) : 0;
  const sy = shake > 0.1 ? rand(-shake, shake) : 0;

  ctx.save();
  ctx.translate(W * 0.5 + sx, H * 0.5 + sy);
  ctx.scale(1.012, 1.012);
  ctx.translate(-W * 0.5, -H * 0.5);

  if (G.state === 'title') {
    drawBackground(G.time, G.time * 24, 'title');
    ctx.restore();
    drawPostEffects(G.time);
    return;
  }

  const mode = G.state === 'boss' || G.state === 'bossDefeat' ? 'boss' : 'game';
  drawBackground(G.time, G.bgScroll, mode);

  for (const o of G.obstacles) drawObstacle(o, G.time);
  for (const item of G.pickups) drawPickup(item, G.time);

  if (G.boss) drawBoss(G.boss, G.time);

  for (const beam of G.beams) drawBeam(beam, G.time);
  for (const pr of G.projectiles) drawProjectile(pr, G.time);
  for (const bolt of G.bolts) drawBolt(bolt, G.time);

  if (G.player) drawPlayer(G.player, G.time);

  drawParticles();
  drawFloaters();

  ctx.restore();
  drawPostEffects(G.time);
}

function updateHud() {
  if (!G.player) return;
  const souls = G.souls.toLocaleString('en-US');
  if (ui.souls.textContent !== souls) ui.souls.textContent = souls;
  const depth = `${Math.floor(G.distance)}`;
  if (ui.distance.textContent !== depth) ui.distance.textContent = depth;
  ui.castBtn.classList.toggle('is-cooling', G.player.castCd > 0.05);
}

function frame(now) {
  const raw = (now - lastFrame) / 1000;
  lastFrame = now;
  const dt = Math.min(raw, 0.033);

  if (G.state !== 'paused') {
    updateGame(dt);
    if (G.state === 'dying' && G.deathTimer > 1.55) showDeathScreen();
  }

  updateHud();
  drawScene();
  requestAnimationFrame(frame);
}

// ---------------------------------------------------------------------------
// Input
// ---------------------------------------------------------------------------

function handlePrimaryAction() {
  if (G.state === 'title') beginRun();
  else if (G.state === 'gameover' || G.state === 'victory') beginRun();
  else if (G.state === 'paused') resumeRun();
  else flap();
}

window.addEventListener('keydown', (e) => {
  const code = e.code;
  if (code === 'Space' || code === 'ArrowUp' || code === 'KeyW') {
    e.preventDefault();
    if (!e.repeat) handlePrimaryAction();
    return;
  }
  if (code === 'KeyJ' || code === 'KeyF' || code === 'KeyK') {
    e.preventDefault();
    G.castHeld = true;
    if (!e.repeat) castSoulBolt();
    return;
  }
  if (code === 'KeyP' || code === 'Escape') {
    e.preventDefault();
    if (G.state === 'paused') resumeRun();
    else togglePause();
  }
});

window.addEventListener('keyup', (e) => {
  if (e.code === 'KeyJ' || e.code === 'KeyF' || e.code === 'KeyK') G.castHeld = false;
});

window.addEventListener('blur', () => {
  G.castHeld = false;
});

canvas.addEventListener('contextmenu', (e) => e.preventDefault());
canvas.addEventListener('pointerdown', (e) => {
  e.preventDefault();
  if (e.button === 2) {
    castSoulBolt();
    return;
  }
  if (G.state === 'playing' || G.state === 'boss') flap();
});

ui.castBtn.addEventListener('pointerdown', (e) => {
  e.preventDefault();
  e.stopPropagation();
  castSoulBolt();
});

ui.startBtn.addEventListener('click', beginRun);
ui.resumeBtn.addEventListener('click', resumeRun);
ui.restartBtn.addEventListener('click', () => {
  ui.pauseScreen.classList.remove('is-visible');
  beginRun();
});
ui.retryBtn.addEventListener('click', beginRun);
ui.againBtn.addEventListener('click', beginRun);
ui.deathTitleBtn.addEventListener('click', returnToTitle);
ui.victoryTitleBtn.addEventListener('click', returnToTitle);
ui.pauseBtn.addEventListener('click', () => {
  if (G.state === 'paused') resumeRun();
  else togglePause();
});
ui.muteBtn.addEventListener('click', toggleMute);

document.addEventListener('visibilitychange', () => {
  if (document.hidden && (G.state === 'playing' || G.state === 'boss' || G.state === 'bossDefeat')) {
    togglePause();
  }
  lastFrame = performance.now();
});

window.addEventListener('resize', resize);

// ---------------------------------------------------------------------------
// Boot
// ---------------------------------------------------------------------------

function boot() {
  resize();
  G.metrics = computeMetrics();
  G.player = makePlayer();
  G.player.y = H * 0.48;
  G.speed = G.metrics.speed;
  makeMotes();
  syncFlasks();
  updateRecordDisplay();
  document.body.classList.toggle('is-muted', G.muted);
  ui.muteBtn.setAttribute('aria-label', G.muted ? 'Unmute sound' : 'Mute sound');
  document.body.dataset.state = 'title';
  ui.titleScreen.classList.add('is-visible');

  if (location.search.includes('nofonts')) {
    document.documentElement.style.setProperty('--serif', '"Palatino Linotype", Palatino, serif');
    document.documentElement.style.setProperty('--body', 'Georgia, serif');
  }

  requestAnimationFrame((now) => {
    lastFrame = now;
    requestAnimationFrame(frame);
  });
}

window.addEventListener('error', (event) => {
  if (!ui.fatalError) return;
  ui.fatalError.textContent = `Hollowwing hit a snag: ${event.message}`;
  ui.fatalError.classList.add('is-visible');
