232: function updatePlayerMotion(dt) {
233:   const p = G.player;
234:   p.castCd = Math.max(0, p.castCd - dt);
235:   p.castAnim = Math.max(0, p.castAnim - dt * 5);
236:   p.iframes = Math.max(0, p.iframes - dt);
237:   p.wing = Math.max(0, p.wing - dt * 2.2);
238: 
239:   if (G.castHeld && p.castCd <= 0) castSoulBolt();
240: 
241:   if (G.startHover > 0 && G.state === 'playing') {
242:     G.startHover -= dt;
243:     const targetY = H * 0.455 + Math.sin(G.time * 2.2) * 7;
244:     p.y = lerp(p.y, targetY, 1 - Math.exp(-dt * 8));
245:     p.vy = 0;
246:     p.rot = lerp(p.rot, 0, 1 - Math.exp(-dt * 8));
247:     emitPlayerTrail(dt);
248:     if (G.startHover <= 0) p.wing = 1;
249:     return;
250:   }
251: 
252:   p.vy += G.metrics.gravity * dt;
253:   p.y += p.vy * dt;
254:   p.knockX = lerp(p.knockX, 0, 1 - Math.exp(-dt * 6));
255:   p.x = G.metrics.playerX + p.knockX;
256:   const rotTarget = clamp(p.vy / 1800, -0.4, 0.55);
257:   p.rot = lerp(p.rot, rotTarget, 1 - Math.exp(-dt * 9));
258: 
259:   const ceiling = 8;
260:   const floor = H - 8;
261:   if (p.y - p.r < ceiling) {
262:     p.y = ceiling + p.r;
263:     if (p.vy < 0) p.vy = 0;
264:     if (G.state === 'playing' || G.state === 'boss') damagePlayer('ceiling');
265:   }
266:   if (p.y + p.r > floor) {
267:     p.y = floor - p.r;
268:     p.vy = -G.metrics.flap * 0.48;
269:     if (G.state === 'playing' || G.state === 'boss') damagePlayer('floor');
270:   }
271: 
272:   emitPlayerTrail(dt);
273: }
