405: function updateBossFight(dt) {
406:   const b = G.boss;
407:   if (!b) return;
408:   const p = G.player;
409: 
410:   updatePlayerMotion(dt);
411:   b.t += dt;
412:   b.flash = Math.max(0, b.flash - dt * 4.5);
413: 
414:   if (b.dead) {
415:     b.deathT += dt;
416:     return;
417:   }
418: 
419:   if (b.enterT < 1) {
420:     b.enterT = Math.min(1, b.enterT + dt / 1.45);
421:     const k = easeOutCubic(b.enterT);
422:     b.x = lerp(W + 190, b.targetX, k);
423:     b.y = b.baseY - H * 0.06 * (1 - k) + Math.sin(b.t * 1.2) * b.bob * 0.4;
424:     if (b.enterT >= 0.72) b.attackCd = Math.min(b.attackCd, 0.9);
425:   } else if (b.dive) {
426:     updateBossDive(dt);
427:   } else {
428:     b.x = lerp(b.x, b.targetX, 1 - Math.exp(-dt * 4));
429:     const targetY = b.baseY + Math.sin(b.t * 1.15) * b.bob;
430:     b.y = lerp(b.y, targetY, 1 - Math.exp(-dt * 2.3));
431: 
432:     if (b.windup) {
433:       b.windup.t -= dt;
434:       if (b.windup.t <= 0) {
435:         const done = b.windup;
436:         b.windup = null;
437:         executeBossAttack(done);
438:       }
439:     } else {
440:       b.attackCd -= dt;
441:       if (b.attackCd <= 0) chooseBossAttack();
442:     }
443:   }
444: 
445:   if (b.enterT >= 1 && !b.dead) {
446:     const contactR = b.hitR * (b.dive ? 0.92 : 0.76);
447:     if (dist(p.x, p.y, b.x, b.y) < contactR + p.r) {
448:       damagePlayer('boss');
449:       p.vy = -G.metrics.flap * 0.65;
450:       p.knockX = -20;
451:     }
452:   }
453: 
454:   G.heartTimer -= dt;
455:   if (G.heartTimer <= 0) {
456:     sound.thump(b.phase2);
457:     G.heartTimer = b.phase2 ? 0.66 : 1;
458:   }
459: 
460:   updateBolts(dt);
461:   updateProjectiles(dt);
462:   updateBeams(dt);
463: }
