465: function chooseBossAttack() {
466:   const b = G.boss;
467:   const p = G.player;
468:   const def = b.def;
469:   const kind = def.patterns[b.patternIndex % def.patterns.length];
470:   b.patternIndex++;
471:   const speedUp = b.phase2 ? 0.84 : 1;
472:   let warn = 0.55;
473:   const data = {};
474: 
475:   if (kind === 'beam') {
476:     warn = 0.92;
477:     data.y = clamp(p.y, H * 0.17, H * 0.83);
478:   } else if (kind === 'rain') {
479:     warn = 0.88;
480:     const total = b.phase2 ? 6 : 4;
481:     const base = p.x;
482:     const spread = Math.min(W * 0.44, 460);
483:     data.xs = [];
484:     for (let i = 0; i < total; i++) {
485:       const t = total === 1 ? 0.5 : i / (total - 1);
486:       data.xs.push(clamp(base + (t - 0.5) * spread + rand(-W * 0.04, W * 0.04), 35, W - 35));
487:     }
488:   } else if (kind === 'dive' || kind === 'dash') {
489:     warn = 0.6;
490:     data.x = clamp(W * (kind === 'dash' ? 0.48 : 0.4), W * 0.3, W * 0.55);
491:     data.y = p.y;
492:   } else if (kind === 'radial') {
493:     warn = 0.66;
494:   } else {
495:     warn = 0.46;
496:   }
497: 
498:   b.windup = {
499:     kind,
500:     t: warn * speedUp,
501:     total: warn * speedUp,
502:     data,
503:   };
504:   sound.tone(kind === 'beam' ? 118 : 86, 0.3, 'sine', 0.035, kind === 'beam' ? 72 : 56);
505: }
