507: function executeBossAttack(w) {
508:   const b = G.boss;
509:   if (!b || b.dead) return;
510:   const p = G.player;
511:   const def = b.def;
512:   const color = def.id === 'choir' ? 'rgba(132, 237, 251, 0.9)' : def.id === 'cinder' ? 'rgba(255, 119, 49, 0.95)' : 'rgba(255, 178, 81, 0.95)';
513:   const core = def.id === 'choir' ? 'rgba(236, 255, 255, 0.98)' : 'rgba(255, 246, 210, 0.98)';
514: 
515:   if (w.kind === 'fan') {
516:     const count = b.phase2 ? 5 : 3;
517:     const baseAngle = Math.atan2(p.y - b.y, p.x - b.x);
518:     const speed = clamp(W * 0.22, 175, 325);
519:     for (let i = 0; i < count; i++) {
520:       const a = baseAngle + (i - (count - 1) / 2) * 0.17;
521:       spawnProjectile(b.x - 22, b.y + 5, Math.cos(a) * speed, Math.sin(a) * speed, {
522:         color, core, r: clamp(8 * b.scale, 6.4, 9.5),
523:       });
524:     }
525:     sound.tone(260, 0.2, 'sawtooth', 0.04, 520);
526:     sound.noiseBurst(0.18, 800, 0.025, 'bandpass');
527:   } else if (w.kind === 'radial') {
528:     const count = b.phase2 ? 14 : 10;
529:     const speed = clamp(W * 0.16, 120, 235);
530:     const offset = Math.random() * TAU;
531:     for (let i = 0; i < count; i++) {
532:       const a = offset + (i / count) * TAU;
533:       spawnProjectile(b.x, b.y, Math.cos(a) * speed, Math.sin(a) * speed, {
534:         color, core, r: clamp(8.5 * b.scale, 6.6, 10),
535:       });
536:     }
537:     sound.tone(330, 0.4, 'triangle', 0.045, 130);
538:     G.shake = Math.max(G.shake, 8);
539:   } else if (w.kind === 'rain') {
540:     const speed = H * (b.phase2 ? 0.52 : 0.43);
541:     for (const x of w.data.xs) {
542:       spawnProjectile(x, -24, rand(-12, 12), speed, {
543:         color,
544:         core,
545:         r: clamp(9 * b.scale, 7, 11),
546:         kind: 'ember',
547:       });
548:     }
549:     sound.tone(150, 0.5, 'sawtooth', 0.05, 70);
550:   } else if (w.kind === 'beam') {
551:     const width = clamp(H * 0.032, 18, 34);
552:     G.beams.push({ y: w.data.y, t: 0, life: 0.42, x2: b.x, width, hit: false });
553:     sound.tone(90, 0.65, 'sawtooth', 0.11, 35);
554:     sound.noiseBurst(0.5, 500, 0.06, 'bandpass');
555:     G.shake = 16;
556:     G.flash = 0.12;
557:     G.flashColor = def.color;
558:   } else if (w.kind === 'dive' || w.kind === 'dash') {
559:     b.dive = {
560:       t: 0,
561:       dur: w.kind === 'dash' ? 1.02 : 1.28,
562:       fromX: b.x,
563:       fromY: b.y,
564:       targetX: w.data.x,
565:       targetY: w.data.y,
566:     };
567:     sound.tone(80, 0.85, 'sawtooth', 0.1, 38);
568:     G.shake = Math.max(G.shake, 10);
569:   }
570: 
571:   b.attackCd = (b.phase2 ? def.cooldown2 : def.cooldown) * (b.phase2 ? 0.9 : 1);
