675: function updateBolts(dt) {
676:   const b = G.boss;
677:   for (let i = G.bolts.length - 1; i >= 0; i--) {
678:     const bolt = G.bolts[i];
679:     bolt.life -= dt;
680:     if (bolt.life <= 0) {
681:       G.bolts.splice(i, 1);
682:       continue;
683:     }
684: 
685:     if (b && !b.dead) {
686:       const dx = b.x - bolt.x;
687:       const dy = b.y - bolt.y;
688:       const d = Math.hypot(dx, dy) || 1;
689:       bolt.vx += (dx / d) * 1250 * dt;
690:       bolt.vy += (dy / d) * 1250 * dt;
691:       const sp = Math.hypot(bolt.vx, bolt.vy) || 1;
692:       const target = Math.max(bolt.speed * 1.04, 760);
693:       bolt.vx = bolt.vx / sp * target;
694:       bolt.vy = bolt.vy / sp * target;
695:     }
696: 
697:     bolt.x += bolt.vx * dt;
698:     bolt.y += bolt.vy * dt;
699: 
700:     // Soul bolts can intercept incoming missiles.
701:     let intercepted = false;
702:     for (let j = G.projectiles.length - 1; j >= 0; j--) {
703:       const pr = G.projectiles[j];
704:       if (dist(bolt.x, bolt.y, pr.x, pr.y) < pr.r + 9) {
705:         G.projectiles.splice(j, 1);
706:         G.bolts.splice(i, 1);
707:         interceptKill(bolt.x, bolt.y);
708:         intercepted = true;
709:         break;
710:       }
711:     }
712:     if (intercepted) continue;
713: 
714:     if (b && !b.dead && b.enterT >= 0.92 && dist(bolt.x, bolt.y, b.x, b.y) < b.hitR + 7) {
715:       G.bolts.splice(i, 1);
716:       damageBoss(bolt.dmg);
717:       continue;
718:     }
719: 
720:     if (bolt.x < -80 || bolt.x > W + 120 || bolt.y < -100 || bolt.y > H + 100) {
721:       G.bolts.splice(i, 1);
722:     }
723:   }
