739:   sound.hitBoss();
740:   updateBossFill();
741:   for (let i = 0; i < 9; i++) {
742:     spawnSpark(b.x + rand(-b.hitR * 0.3, b.hitR * 0.3), b.y + rand(-b.hitR * 0.3, b.hitR * 0.3), 1, 'rgba(163, 244, 255, ALPHA)', 3);
743:   }
