745:   if (!b.phase2 && b.hp <= b.maxHp * 0.5) {
746:     b.phase2 = true;
747:     b.windup = null;
748:     b.attackCd = 0.75;
749:     sound.roar();
750:     G.flash = 0.2;
751:     G.flashColor = b.def.id === 'choir' ? '#b3f1ff' : '#ffb06c';
752:     G.shake = 18;
